const APP_VERSION='__APP_VERSION__';
const RELEASES=[{version:'__APP_VERSION__',name:"Ẩn Tình",title:"Ẩn tình: Truyện ký cấp 0–88 viết lại với nhiều cú lật khó đoán",text:"Hai mươi mốt chương đầu của “Hằng Nguyệt và Huyết Nguyệt” được viết lại. Mỗi chương vẫn giữ trận đấu và Tâm đắc cũ, nhưng nay gài thêm những chi tiết tưởng nhỏ mà về sau đổi nghĩa cả câu chuyện: một cái gáo sứt quai, một chiếc đòn gánh cũ, ba nút thắt trên tua kiếm, một con rùa rụt cổ. Có người thân trở mặt, có bí mật của chính sư phụ. Chương đã đọc có thể mở đọc lại bất cứ lúc nào.",tags:["Tu vi", "Truyện ký"],items:["21 chương (khai cuộc tới cấp 88) viết lại, thêm tình tiết bất ngờ và manh mối cho chặng cuối.", "Bài học (Tâm đắc) của từng chương giữ nguyên tinh thần.", "Vài lời trong Giang hồ kỳ ngộ được chỉnh cho khớp mạch truyện mới; lịch gặp không đổi.", "Chặng cấp 90–100 sẽ được viết lại chi tiết ở bản kế tiếp."]},{version:'2.10.0',name:"Thiên Môn",title:"Thiên Môn: từ cấp 91, mỗi cấp khó gấp đôi cấp trước",text:"Chặng cuối của cõi người nay dốc dần như bậc thang lên trời: cấp 91 tốn 4 điểm, rồi 8, 16 … tới 1.024 điểm ở cấp 99. Cấp 100, ngưỡng từ người thành Thần, là ải nặng nhất: 2.048 điểm, bằng cả chín cấp trước cộng lại. Tổng điểm tới cấp 100 gần như giữ nguyên (8.180), nên không ai tụt cấp và hành trình vẫn đi hết trong khoảng 3–4 năm.",tags:["Tu vi", "thang cấp"],items:["Cấp 91–99: mỗi cấp tốn gấp đôi cấp trước (4 → 1.024 điểm).", "Cấp 100 tốn 2.048 điểm, là cấp khó vượt nhất.", "Cấp 1–90 giữ nguyên; không mốc nào cao hơn trước.", "Bảng thang, Lộ trình tu luyện và Tâm pháp tu luyện ghi rõ cách tính mới."]},{version:'2.9.1',name:"Giờ Chuẩn",title:"Giờ chuẩn: kiểm thử lời chào Giang hồ không còn phụ thuộc giờ chạy",text:"Không đổi tính năng hay dữ liệu. Bài kiểm thử tự động của lời chào Giang hồ nay chạy ở giờ sáng cố định, nên quy trình phát hành không còn bị đỏ khi chạy vào buổi chiều. Lời chào trong ứng dụng vẫn đổi theo sáng, trưa, chiều, tối như cũ.",tags:["Giang hồ", "kiểm thử"],items:["Lời chào theo giờ trong ngày giữ nguyên: sáng, trưa, chiều, tối.", "Chỉ sửa bài kiểm thử phong cách Giang hồ, giữ nguyên kỳ vọng “các hạ”.", "Không đổi dữ liệu, lược đồ, migration hay biến môi trường."]},{version:'2.9.0',name:"Thư Pháp",title:"Thư pháp: tiêu đề Giang hồ viết bằng nét bút lông kiếm hiệp",text:"Ở phong cách Giang hồ, tiêu đề trang, tiêu đề khung, tiêu đề hộp thoại, ấn cảnh giới và danh hiệu thanh bên nay dùng phông bút lông Potta One, có đủ dấu tiếng Việt, mang dáng chữ trên áp phích truyện kiếm hiệp. Chữ thường vẫn là chữ có chân dễ đọc. Phong cách Thiền không đổi.",tags:["giang hồ", "giao diện"],items:["Tiêu đề dùng phông bút lông Potta One, độ đậm 400, không in đậm giả; chữ phụ nhỏ trong tiêu đề giữ chữ có chân.", "Phông tự lưu trên máy chủ của ứng dụng (giấy phép SIL OFL 1.1), chỉ Latin và tiếng Việt, khoảng 35 KB; tải sớm cùng lúc với giao diện.", "Phong cách Thiền không tải phông này."]},{version:'2.8.0',name:"Huyết Nguyệt Lộ",title:"Huyết Nguyệt lộ: tranh động phe ác và lộ trình gặp gỡ, đối kháng, vượt cấp",text:"Huyết Nguyệt Giáo chủ và mười Nguyệt Sứ nay có tranh động riêng, mỗi kẻ một tà công: khói Mê Hồn Hương, đèn nghìn mặt, song đao chớp lóe, xoáy Thôn Nguyệt Quyết… Trang Tu vi có thêm khung Huyết Nguyệt lộ cho thấy mình đã vượt ai, sắp đối đầu ai, và Giáo chủ đang ở cấp mấy.",tags:["Tu vi", "giang hồ"],items:["Tranh động cho Giáo chủ Lệ Vô Khuyết và Thập Nguyệt Sứ; bật giảm chuyển động thì tranh đứng yên.", "Trang phe ác trong truyện vẽ đúng người đang nói trên nền Huyết Nguyệt đài.", "Khung Huyết Nguyệt lộ: ải đột phá và đối thủ theo cấp, trạng thái Đã vượt qua · Sắp đối đầu · Chưa lộ diện.", "Thanh tu luyện song hành so cấp của hiệp khách với Giáo chủ; bấm một đối thủ đã gặp để đọc lại chương."]},{version:'2.7.0',name:"Kỳ Ngộ",title:"Kỳ ngộ: 22 nhân vật phụ xuất hiện ngẫu nhiên trên đường tu luyện",text:"Ở những cấp không có chương truyện, hiệp khách có thể gặp một trong 22 nhân vật phụ: người giúp đỡ, kẻ gây khó, sát thủ hay người thử thách. Mỗi người gặp hai lần, ở những cấp khác nhau với mỗi hiệp khách; mỗi lần gặp kết bằng một Tâm đắc.",tags:["Tu vi", "giang hồ"],items:["22 nhân vật, 44 kỳ ngộ, gồm thiền sư Không Nguyệt (tinh thần 95) và võ sư Mạc Trấn Hải (nội lực 95).", "Vượt cấp có kỳ ngộ thì bảng đọc tự mở, sau chương truyện nếu có.", "Khung \"Giang hồ kỳ ngộ\" trong Tu vi: người đã gặp, người chưa lộ diện, cấp gặp kế tiếp.", "Cấp gặp cố định theo tài khoản, giống nhau trên mọi thiết bị.", "Bảng vàng thêm danh hiệu Tứ hải giai huynh đệ khi gặp đủ 22 nhân vật."]},{version:'2.6.0',name:"Song Nguyệt",title:"Song nguyệt: cốt truyện mới Hằng Nguyệt và Huyết Nguyệt, 27 chương tới cấp 100",text:"Truyện ký được viết lại từ đầu. Hiệp khách gánh nước đi lên từng cấp; Huyết Nguyệt Giáo chủ, đại sư huynh năm xưa, tu luyện song hành bằng cách hút sức người khác. Mười Nguyệt Sứ, mỗi kẻ là một thói xấu trong làm việc, lần lượt chặn đường dưới cấp 80. Từ cấp 80 là những trận giao thủ trực tiếp, rồi sự thật sau cấp 95, đại chiến ở cấp 99 và Song thần ở cấp 100.",tags:["Tu vi", "giang hồ"],items:["27 chương và khai cuộc; chương tự mở khi vượt mốc, đọc lại trong Lộ trình tu luyện.", "Thập Nguyệt Sứ: trì hoãn, phân tâm, nóng vội, tự nghi ngờ, ôm đồm, cầu toàn, kiệt sức, so sánh, cô lập, tuyệt vọng; mỗi trận kết bằng một Tâm đắc.", "Thiền sư Không Nguyệt dẫn lên núi tuyết, võ sư Mạc Trấn Hải dẫn xuống biển bế quan.", "Trang phe ác hiện cảnh Huyết Nguyệt đài với trăng máu; Tâm đắc ghi cấp của Giáo chủ lúc ấy.", "Chương mới hiện là \"Chưa đọc\" kể cả khi đã đọc truyện cũ; danh hiệu đọc truyện đã đạt vẫn giữ."]},{version:'2.5.0',name:"Thăng Thiên",title:"Thăng thiên: thang 103 cấp, mỗi cấp một danh xưng, ải đột phá và Thần cảnh",text:"Tu vi có thang cấp mới: 100 cấp, mỗi cấp một danh xưng; cấp 100 là đột phá thành Thần, thêm ba thần cấp tới Thần Vương. Điểm cần tích lũy giảm 20%, nên phần lớn hiệp khách lên thêm vài cấp ngay. Không ai bị tụt cấp.",tags:["Tu vi", "giang hồ"],items:["Mỗi cấp một danh xưng, từ Sơ Tâm Khởi Bước (cấp 1) tới Nhân Gian Cực Cảnh (cấp 99), Thành Thần (cấp 100) và Thần Vương (cấp 103).", "Cấp 10, 20 … 100 là ải đột phá sang cảnh giới mới, tốn chừng ba lần cấp thường.", "Cấp 100 cần 8.184 điểm, giảm 20%: khoảng 3–4 năm nếu mỗi ngày tích lũy 5–7 điểm.", "Bảng \"Xem thang 103 cấp\" có điểm từng cảnh giới và danh xưng mọi cấp; cấp đang ở được tô.", "Qua ải cấp 100 có nghi thức Đột phá thành Thần; Bảng vàng thêm danh hiệu Thành Thần."]},{version:'2.4.0',name:"Kiên Cố",title:"Kiên cố: Cài đặt và chi tiết nhiệm vụ không còn phụ thuộc chữ tiêu đề",text:"Bản bảo trì: các nhóm trong Cài đặt và phần Checklist của chi tiết nhiệm vụ nay được nhận ra bằng mã ẩn thay vì chữ tiêu đề. Giao diện không đổi; đổi chữ (như phong cách Giang hồ) không còn có thể làm lệch nhóm.",tags:["bảo trì"],items:["Mỗi nhóm Cài đặt mang mã riêng (hồ sơ, tài khoản, thông báo, tổng kết tuần, dữ liệu, hướng dẫn, phiên đăng nhập).", "Khối thông báo Công việc · Việc hằng ngày · Điểm tích lũy tìm nhóm Thông báo theo mã.", "Chi tiết nhiệm vụ tìm phần Checklist theo lớp, nên thanh tiến độ trực tiếp và các nút luôn đặt đúng chỗ.", "Không đổi giao diện, chữ hay dữ liệu."]},{version:'2.3.0',name:"Chiến Báo",title:"Chiến báo: thân tổng kết tuần bằng giọng giang hồ",text:"Khi tài khoản chọn phong cách Giang hồ, toàn bộ tổng kết tuần (email và bản xem trước trong ứng dụng) dùng giọng giang hồ: đại sự, nhiệm vụ, lỡ hẹn, tiên quyết, kế sách tuần tới, nhịp hành sự. Link chia sẻ công khai vẫn dùng giọng thường cho người ngoài.",tags:["báo cáo", "giang hồ"],items:["Phần thân chiến báo tuần: số liệu tổng, phân bố, từng đại sự, tiên quyết, kế sách tuần tới, chiêu kế tiếp, nhịp hành sự tuần tới đều theo giọng giang hồ.", "Tên việc, tên dự án, bước checklist giữ nguyên như bạn đã đặt.", "Link chia sẻ báo cáo công khai luôn dùng giọng thường, vì người xem có thể không dùng ứng dụng.", "Sửa dòng ngày dưới tiêu đề chiến báo (trước đây lặp lại chữ \"CHIẾN BÁO ĐẠI SỰ\").", "Thiền, Giang hồ nhẹ và người chưa chọn phong cách giữ tổng kết tuần như cũ."]},{version:'2.2.0',name:"Thanh Âm",title:"Thanh âm: chuông đồng và tiếng suối cho đồng hồ tập trung",text:"Đồng hồ tập trung (ở Giang hồ là Nén hương bế quan) có thêm ô Âm thanh: chuông đồng khi bắt đầu và khi hết giờ, kèm tiếng suối êm khi đang đếm nếu muốn. Mặc định tắt.",tags:["tập trung", "âm thanh"],items:["Ba lựa chọn: Tắt (mặc định), Chuông đồng, Chuông đồng và tiếng suối. Lưu trên thiết bị.", "Một tiếng chuông khi bắt đầu đếm, ba tiếng khi hết giờ; tiếng suối chỉ chạy khi đang đếm, dừng khi tạm dừng, đặt lại, rời chế độ tập trung hoặc ẩn tab.", "Âm thanh tạo ngay trên thiết bị, không tải thêm tệp. Dùng chung được với Nhạc nền (sáo trúc).", "Có ở cả phong cách Thiền và Giang hồ."]},{version:'2.1.0',name:"Danh Trận",title:"Danh trận: tên cột mặc định theo giang hồ (tùy chọn)",text:"Ở phong cách Giang hồ, bạn có thể bật Tên cột giang hồ: các cột còn tên mặc định hiện thành Kế sách · Chờ xuất chiêu · Đang hành sự · Công thành. Chỉ đổi chữ hiển thị, tên cột trong dữ liệu giữ nguyên.",tags:["giao diện", "giang hồ"],items:["Bật ở Cài đặt → Giao diện → Tên cột giang hồ, hoặc bảng lệnh \"Bật / tắt tên cột giang hồ\". Mặc định tắt, lưu trên thiết bị.", "Áp cho tiêu đề cột, dải tab cột trên điện thoại, nút và ô chọn trạng thái trong chi tiết nhiệm vụ, nhãn đọc của nút thêm và nút chuyển cột.", "Cột bạn đã đặt tên riêng giữ nguyên; hộp đổi tên cột vẫn điền tên trong dữ liệu.", "Giang hồ nhẹ và Thiền giữ tên cột thường."]},{version:'2.0.0',name:"Truyền Âm",title:"Truyền âm: phong cách đi theo tài khoản, email và thông báo giọng giang hồ",text:"Chọn phong cách ở một thiết bị thì các thiết bị khác cũng đổi theo khi mở. Khi chọn Giang hồ, email nhắc hạn, chiến báo tuần và thông báo đẩy cũng dùng giọng giang hồ.",tags:["giang hồ", "đồng bộ", "thông báo"],items:["Phong cách (Thiền, Giang hồ, Giang hồ nhẹ) lưu theo tài khoản khi bạn tự đổi; thiết bị khác áp theo khi mở hoặc khi nhận dữ liệu mới.", "Người dùng chưa từng đổi phong cách: không có gì thay đổi, mỗi thiết bị giữ lựa chọn riêng như trước.", "Email nhắc hạn bằng giọng giang hồ (Truyền thư kỳ hạn, Lỡ hẹn, Sắp tới kỳ, các hạ); chiến báo tuần có tiêu đề Chiến báo đại sự. Tên việc, tên dự án giữ nguyên.", "Thông báo đẩy hằng ngày theo phong cách của thiết bị đó.", "Giang hồ nhẹ và Thiền giữ email giọng thường như cũ."]},{version:'1.99.0',name:"Bảng Vàng",title:"Bảng vàng: 18 danh hiệu giang hồ trong trang Tu vi",text:"Trang Tu vi có thêm Bảng vàng: 18 danh hiệu tính từ chính việc bạn đã làm (nhiệm vụ công thành, chuỗi việc hằng ngày, đại sự viên mãn, hồi vốn, ghi chú, cảnh giới, truyện ký). Đạt danh hiệu mới thì được báo một lần; không cần nhập thêm gì.",tags:["tu vi", "giang hồ"],items:["7 nhóm: Công thành (1, 25, 100, 500 nhiệm vụ), Khổ luyện (chuỗi 7, 30, 100 ngày), Đại sự (1, 5 đại sự viên mãn), Ngân khố (hồi vốn đầu tiên), Tàng thư (10, 50 quyển), Tu vi (4 cảnh giới), Truyện ký (5 và 20 chương).", "Danh hiệu chưa đạt có thanh tiến độ và số \"23/25\"; đã đạt mang ấn son.", "Đạt danh hiệu mới thì có thông báo một lần, thiết bị khác không báo lại. Lần đầu mở Bảng vàng không báo dồn các danh hiệu đã đạt từ trước.", "Không thêm gì vào dữ liệu: Bảng vàng tính từ dữ liệu sẵn có; dấu đã báo dùng biên nhận đã đọc của tài khoản."]},{version:'1.98.0',name:"Âm Lịch",title:"Âm lịch: ngày âm, 24 tiết khí và lời chào theo tiết trong phong cách Giang hồ",text:"Ở phong cách Giang hồ, Hoàng lịch ghi ngày âm dưới mỗi ngày dương và đánh dấu 24 tiết khí; Tổng quan có dòng ngày âm, năm can chi và lời khuyên theo tiết. Tất cả tính ngay trên thiết bị, không cần mạng.",tags:["lịch", "giang hồ"],items:["Lưới tháng: số ngày âm dưới ngày dương, mùng 1 ghi cả tháng (tháng nhuận có chữ n); ngày giao tiết ghi tên tiết, điện thoại hiện chấm son.", "Tiêu đề tháng ghi khoảng ngày âm và năm can chi; dạng danh sách ghi ngày âm cạnh từng ngày.", "Tổng quan: \"Mùng 4 tháng Mười · năm Bính Ngọ · Tiết Lập đông\" kèm lời khuyên theo tiết; Giang hồ nhẹ chỉ ghi ngày và tiết.", "Thuật toán âm lịch Việt Nam (múi giờ +7), khớp Tết Bính Ngọ 17/2/2026, tháng nhuận 2023 và 2025, Tết Đinh Mùi 6/2/2027."]},{version:'1.97.0',name:"Ấn Son",title:"Ấn son: con dấu công thành, nén hương bế quan, nghi thức Đột phá",text:"Phong cách Giang hồ có thêm những khoảnh khắc riêng: con dấu son khi hoàn thành nhiệm vụ, nén hương cháy dần khi bế quan, danh hiệu cảnh giới trên thanh bên và nghi thức Đột phá khi Tu vi sang cảnh giới mới.",tags:["giao diện", "giang hồ", "tu vi"],items:["Ấn son công thành: lời chúc mang con dấu son \"Công thành\" thay pháo hoa; về lại bảng thì thẻ vừa xong được đóng dấu rồi mờ dần.", "Nén hương bế quan: que hương cạnh đồng hồ ngắn dần theo thời gian, đốm lửa sáng khi đang đếm.", "Danh hiệu trên thanh bên: cảnh giới, trọng, cấp và vòng tiến cảnh tới cấp kế; bấm để mở Tu vi.", "Nghi thức Đột phá: lưu công lực mà đột phá sang cảnh giới mới (từ Tam lưu cao thủ, cấp 11) thì hiện bảng nghi thức có hình hiệp khách; chương truyện ký (nếu có) mở sau đó. Tắt cùng Thông báo điểm nghiệp.", "Ấn chương: ảnh đại diện chữ viết tắt thành con dấu vuông viền son kép.", "Tắt con dấu và nén hương ở Cài đặt → Giao diện → Hiệu ứng ấn son, nén hương. Thiết bị bật giảm chuyển động thì mọi thứ đứng yên."]},{version:'1.96.0',name:"Chú Giải",title:"Chú giải: hiểu Giang hồ dễ hơn, chọn được mức Giang hồ nhẹ",text:"Chữ giang hồ nay luôn có nghĩa thường đi kèm: rê chuột hoặc nhấn giữ để xem, có Bảng chú giải để tra, bảng lệnh hiểu cả hai cách gọi. Ai thích họa tiết mà vẫn muốn chữ quen thuộc có thể chọn Giang hồ nhẹ.",tags:["giao diện", "giang hồ"],items:["Nghĩa thường: tiêu đề, nút, nhãn được đổi sang chữ giang hồ mang lời nhắc \"Nghĩa thường: …\". Máy tính rê chuột để xem; điện thoại nhấn giữ để hiện bong bóng, lần chạm đó không bấm nút.", "Bảng chú giải: 50 chữ giang hồ và nghĩa thường, chia 4 nhóm, ô tìm hai chiều (gõ không dấu cũng được). Mở từ Cài đặt → Giao diện hoặc bảng lệnh.", "Khẩu quyết hai chiều: ở Giang hồ, lệnh trong bảng lệnh mang tên giang hồ, nghĩa thường nằm ở dòng gợi ý; gõ \"cài đặt\" hay \"cơ quan\" đều ra. Tên việc của bạn giữ nguyên.", "Giang hồ nhẹ: tắt \"Lời lẽ giang hồ\" trong Cài đặt → Giao diện (hoặc bảng lệnh) để giữ son đỏ, giấy dó mà chữ vẫn quen thuộc. Lưu trên thiết bị.", "Lời mời một lần ở cuối Tổng quan cho người đang dùng Thiền: Bật thử hoặc Ẩn; đã ẩn thì không hiện lại, kể cả trên thiết bị khác."]},{version:'1.95.0',name:"Bổ Khuyết",title:"Bổ khuyết: lấp các chỗ Giang hồ còn sót giọng Thiền",text:"Khi bật phong cách Giang hồ, các chữ còn sót giọng Thiền ở tab Tổng quan, menu Thêm, hộp nhiệm vụ cần chú ý, chiến báo tuần, hộp hỏi đăng xuất và trang Bí kíp nhập môn nay đều mang giọng Giang hồ. Có thêm một bài kiểm thử tự động để màn hình mới không bị sót chữ.",tags:["giao diện", "giang hồ"],items:["Tab Tổng quan thành Tổng đàn, kèm số đại sự đang vận hành; menu Thêm trên điện thoại thành Hậu viện; số dự án ở trang chủ thành đại sự.", "Hộp nhiệm vụ cần chú ý: tiêu đề và hai tab Lỡ hẹn / Sắp tới kỳ; nút đánh dấu chiêu thức trên thẻ đọc là Công thành chiêu; nhãn ô lịch đọc số nhiệm vụ.", "Chiến báo tuần: thanh công cụ xem trước, nút chia sẻ và nút đóng mang giọng Giang hồ.", "Hỏi đăng xuất: nút xác nhận ghi Đăng xuất (trước đây ghi Lưu), sang Giang hồ thành Hạ sơn.", "Trang Bí kíp nhập môn (hướng dẫn sử dụng) đổi trọn sang giọng Giang hồ.", "Bài kiểm thử độ phủ mới đi qua mọi màn hình, hộp thoại và màn hình đăng nhập ở 390/820/1440 px; chữ nào còn giọng Thiền mà chưa có lý do giữ sẽ làm bài báo đỏ."]},{version:'1.94.0',name:"Khinh Công",title:"Khinh công: giao diện Giang hồ tải nhanh, nhẹ hơn",text:"Phông chữ có chân Noto Serif nay nằm ngay trên máy chủ của ứng dụng, không còn chờ Google Fonts; bộ chuyển ngữ Giang hồ quét mỗi lần dựng màn hình đúng một lượt và nhớ các chữ không cần đổi.",tags:["giao diện", "hiệu năng"],items:["Phông Noto Serif (Latin + tiếng Việt, đậm 600/700) tự lưu, chỉ tải khi bật Giang hồ; phông tiêu đề được tải sớm song song với giao diện. Thiền không tải phông này.", "Bỏ yêu cầu tới Google Fonts cho Noto Serif, vốn chặn hiển thị ở cả hai phong cách; dùng được cả khi mất mạng (có trong bộ nhớ ngoại tuyến).", "Bộ chuyển ngữ: mỗi lần dựng lại chỉ quét các phần mới một lần (trước đây cây con thêm chồng nhau bị quét lại khoảng 4 lần), nhớ chữ chắc chắn không đổi, dò vùng nội dung người dùng theo từng phần tử một lần.", "Bảng 180 nhiệm vụ: phần việc của bộ chuyển ngữ mỗi lần dựng lại giảm khoảng một nửa."]},{version:'1.93.0',name:"Lộ Trình",title:"Lộ trình tu luyện: biết hiệp khách đang ở chặng nào trên trăm cấp",text:"Trang Tu vi có dòng thời gian 100 cấp: 10 cảnh giới, mỗi cảnh giới hai chặng, cuối mỗi chặng là một chương truyện ký. Khối “đang ở đây” cho biết hiệp khách ở chặng nào, đã qua mấy cấp, còn bao nhiêu điểm tới chương kế.",tags:["tu vi", "lộ trình"],items:["Khối “đang ở đây”: chặng hiện tại trên 20 chặng, cấp, cảnh giới, trọng, số cấp đã qua của chặng, điểm còn thiếu tới chương kế, thanh tiến trình theo điểm.", "10 cảnh giới xếp thành con đường: đã qua (dấu ✓), đang tu luyện, chưa tới; mỗi cảnh giới ghi cấp, điểm mỗi cấp và khoảng tu vi.", "20 chặng, mỗi chặng 5 vạch cấp; chặng đã qua bấm để đọc chương, chặng hiện tại có nhãn “Đang ở đây”, chặng sau ghi “Mở ở cấp N”.", "Khung Truyện ký của bản trước gộp vào Lộ trình; Khai cuộc nằm ở đầu con đường.", "Nhãn Đã đọc / Chưa đọc cập nhật ngay khi dấu đã đọc của tài khoản tải xong."]},{version:'1.92.0',name:"Truyện Ký",title:"Truyện ký giang hồ: mỗi 5 cấp, hiệp khách kể một chặng đường",text:"Mục Tu vi có cốt truyện riêng: Khai cuộc và 20 chương, từ ngày gánh nước dưới chân núi Vân Mộng tới lúc thành Võ lâm chí tôn. Mỗi khi vượt một mốc 5 cấp, bảng hội thoại tự hiện kể chặng vượt khó vừa qua.",tags:["tu vi", "truyện"],items:["Vượt cấp 5, 10, 15 … 100 khi lưu công lực thì chương tương ứng tự hiện: tranh hiệp khách, lời kể, lời sư phụ Tùng Hạc, Tiểu Mộc, Hàn Phong; trang cuối là Tâm đắc kèm cấp hiện tại.", "Lật trang bằng nút Tiếp / Trước hoặc phím mũi tên; Esc hay Khép sách để đóng.", "Khung “Truyện ký giang hồ” trong trang Tu vi: đọc lại chương đã mở, xem chương kế mở ở cấp nào và còn bao nhiêu điểm.", "Lời thoại theo hiệp khách các hạ chọn: danh hiệu giang hồ, chàng / nàng, sư huynh / sư tỷ.", "Đã đọc trên thiết bị này thì thiết bị khác không hiện lại; dữ liệu Tu vi không đổi."]},{version:'1.91.0',name:"Cơ Quan",title:"Giang hồ trọn vẹn: Cơ quan, Nhập môn, Truyền thư, Phong ấn, Phế tích",text:"Ở phong cách Giang hồ, phần còn lại của ứng dụng cũng nói giọng giang hồ: Cài đặt thành Cơ quan, đăng nhập thành Nhập môn, chuông thông báo thành Truyền thư, Lưu trữ thành Phong ấn, Thùng rác thành Phế tích, đồng bộ xong là thông mạch, mất mạng là ẩn cư.",tags:["giao diện", "chữ"],items:["Cơ quan: Hành trạng, Danh tính & phòng vệ, Truyền thư (Nhiệm vụ · Nhật khóa · Tu vi), Chiến báo tuần, Chiến báo ngân khố tuần, Bí kíp nhập môn, Phiên nhập môn, nút Hạ sơn; Phát lệnh bài, Thu chiêu. Nhóm Giao diện, Dữ liệu & đồng bộ và nút Xóa dữ liệu giữ nguyên chữ.", "Nhập môn: Trở lại giang hồ của các hạ, Ám hiệu (mật khẩu), Quên ám hiệu?, Ghi danh; lời báo lỗi đăng nhập nói rõ bằng giọng giang hồ. Biểu tượng ở màn hình này cũng đổi sang sắc son.", "Truyền thư: nhóm Lỡ hẹn · Sắp tới kỳ · Trọng yếu, dòng tóm tắt, Biên niên mới. Phong ấn: Giải ấn để làm tiếp, Nhiệm vụ đã phong ấn. Phế tích: Mục trong Phế tích, Nhóm này trống trơn, Dọn sạch Phế tích?", "Trạng thái đồng bộ: Đã thông mạch lúc 09:00, Ẩn cư, Chưa thông mạch được. Thông báo nhanh: Đã ghi vào sổ, Đã phong ấn đại sự, Đã giải ấn đại sự…", "Tên đại sự, nhiệm vụ, quyển, mục trong Phế tích và tên hiển thị của các hạ giữ nguyên; dữ liệu lưu không đổi chữ."]},{version:'1.90.0',name:"Tàng Bảo",title:"Giang hồ tàng bảo: Tàng thư, Ngân khố, Bảo khố",text:"Ở phong cách Giang hồ, chữ trong Ghi chú (Tàng thư), Phân bổ tài nguyên (Ngân khố) và Tài nguyên (Bảo khố) đổi theo bảng thuật ngữ: ghi chú → quyển, chi → xuất ngân, thu → thu ngân, thu hồi vốn → hồi vốn, dòng tiền → ngân lưu.",tags:["giao diện", "chữ"],items:["Tàng thư: Chép quyển mới, Ghim quyển, Nhãn quyển, Nhắc tại hạ, Các chiêu cần luyện, Liên kết với đại sự, Họa tiết quyển.", "Ngân khố: Đã xuất ngân, Đã thu ngân, Hồi vốn, Đồ hòa vốn, Ngân lưu theo tháng, Xuất ngân theo đại sự; nút + Xuất ngân / + Thu ngân; biểu mẫu “Thêm khoản xuất ngân”, “Số ngân lượng (₫)”.", "Bảo khố: Cất vào bảo khố; tệp ở Phế tích vẫn được tính.", "Tên quyển, nội dung, nhóm, hạng mục, ghi chú khoản thu chi và tên tệp của các hạ giữ nguyên; bấm gợi ý hạng mục vẫn chép đúng chữ gốc."]},{version:'1.89.0',name:"Nhật Khóa",title:"Giang hồ thường nhật: Hoàng lịch, Bế quan, Nhật khóa",text:"Ở phong cách Giang hồ, chữ trong Hoàng lịch, Bế quan (kể cả phiên bế quan và nén hương) và Nhật khóa (trang chính, biểu mẫu, chiến báo) đổi theo bảng thuật ngữ.",tags:["giao diện", "chữ"],items:["Hoàng lịch: Liệt kê / Lưới tháng, Kỳ hạn, Chưa định ngày, Sự vụ trong ngày.", "Bế quan: “Nhất tâm bất loạn”, 3 nhiệm vụ trọng yếu, Tới kỳ hôm nay; trong phiên: Nén hương bế quan, Nhập định / Tạm nghỉ, Xuất quan.", "Nhật khóa: Thêm nhật khóa, Khổ luyện liền N ngày, Hưu tức hôm nay, Xem công phu, Tiến cảnh tuần này; biểu mẫu Tên môn, Số buổi luyện mỗi tuần.", "Chiến báo nhật khóa: Tỷ lệ công thành, Lượt đã luyện, Thâm hậu / Vững vàng / Đang thành hình / Cần khổ luyện, Bí kíp cải thiện; lời luận tự động theo giọng giang hồ.", "Tên việc, môn nhật khóa, dự án và tâm đắc của các hạ giữ nguyên."]},{version:'1.88.0',name:"Hành Sự",title:"Giang hồ hành sự: Tổng đàn, bảng cáo thị, trận đồ và biểu mẫu nhiệm vụ",text:"Ở phong cách Giang hồ, chữ bên trong Tổng đàn, bảng của từng đại sự, Trận đồ, biểu mẫu nhiệm vụ và đại sự đổi theo bảng thuật ngữ: việc → nhiệm vụ, dự án → đại sự, quá hạn → lỡ hẹn, hạn → kỳ hạn, checklist → chiêu thức, tiến độ → tiến cảnh, bốn mức cấp bách.",tags:["giao diện", "chữ"],items:["Tổng đàn: Lỡ hẹn & sắp tới kỳ, Nhiệm vụ hôm nay, Toàn cảnh giang hồ, Tiến cảnh từng đại sự, Khởi đại sự.", "Bảng cáo thị: Bố cục, Thêm nhiệm vụ, Lỡ hẹn · 05-11, Kỳ hạn · 08-11, Chiêu kế tiếp, “Trọng yếu, hỏa tốc” · “Trọng yếu, thong thả” · “Hỏa tốc, thứ yếu” · “Thứ yếu, thong thả”.", "Trận đồ: Tầm nhìn, Nhiệm vụ cần định ngày, Định ngày hôm nay.", "Biểu mẫu: Nhiệm vụ mới, Chi tiết nhiệm vụ, Cấp bách, Ngày giờ & kỳ hạn, Chiêu thức, Luận bàn, Phong ấn nhiệm vụ; nút Hủy → Thôi.", "Tên dự án, việc, cột, nhãn, từ khóa và chiêu của các hạ giữ nguyên; dữ liệu lưu không đổi chữ."]},{version:'1.87.0',name:"Nhập Môn",title:"Giang hồ nói giang hồ: tên mục, thanh trên và tiêu đề trang",text:"Ở phong cách Giang hồ, tên các mục đổi theo bảng thuật ngữ đã duyệt, kèm dòng nhỏ nghĩa quen thuộc: Tổng đàn, Bảng cáo thị, Hoàng lịch, Trận đồ, Tu vi, Ngân khố, Nhật khóa, Bế quan, Tàng thư, Bảo khố, Phong ấn, Phế tích, Biên niên, Cơ quan. Phong cách Thiền giữ nguyên chữ.",tags:["giao diện", "chữ"],items:["Thanh bên: tên giang hồ ở dòng chính, nghĩa thường ở dòng nhỏ; nhóm Hành sự, Thế trận, Kho tàng, Đại sự.", "Thanh trên: đường dẫn theo tên mới, ô “Truy tìm nhiệm vụ…”, nút Truyền thư; bảng lệnh “Các hạ muốn thi triển chiêu gì?”.", "Tiêu đề từng màn hình đổi giọng giang hồ; Tổng đàn chào theo giờ (bình minh, chính ngọ, nắng chiều, trăng lên); Biên niên ghi kèm tên phiên bản.", "Tên dự án, việc, cột, ghi chú, việc hằng ngày của các hạ giữ nguyên dù trùng chữ giao diện.", "Chuyển về Thiền là chữ trở lại ngay, không cần tải lại."]},{version:'1.86.0',name:"Chu Mặc",title:"Phong cách Giang hồ: son đỏ, giấy dó, họa tiết kiếm hiệp",text:"Cài đặt → Giao diện có thêm Phong cách: Thiền (như trước) hoặc Giang hồ. Giang hồ đổi màu tím sang son, nền sang giấy dó, thêm dãy núi mực, triện son, tường vân và chữ có chân. Bản này chưa đổi chữ.",tags:["giao diện"],items:["Chọn ở Cài đặt → Giao diện → Phong cách, hoặc gõ “Phong cách Giang hồ” trong bảng lệnh (Ctrl/⌘ K). Lưu trên từng thiết bị, giống Sáng/Tối.", "Màu thương hiệu tím → son, nền → giấy dó, chữ → mực nâu; màu mang nghĩa và màu dự án do các hạ chọn giữ nguyên.", "Nền có dãy núi mực mờ; thanh bên viền đôi như cuộn thư; tiêu đề chữ có chân với nét bút son; tiêu đề khung có triện son; hộp thoại viền son.", "Dùng được với nền tối và tương phản cao; chữ vẫn đạt tương phản ≥ 4,5:1.", "Chữ giang hồ (bảng thuật ngữ đã duyệt) sẽ đến ở các bản sau."]},{version:'1.85.0',name:"Bách Cấp",title:"Tu vi có 100 cấp: 10 cảnh giới, mỗi cảnh giới 10 trọng",text:"Điểm tích lũy giờ có 100 cấp. Cảnh giới sau tốn gấp đôi cảnh giới trước: 1 điểm mỗi cấp ở Sơ nhập giang hồ, 2 điểm ở Tam lưu cao thủ… 512 điểm ở Võ lâm chí tôn; cấp 100 cần 10.230 điểm.",tags:["Điểm tích lũy"],items:["10 cảnh giới: Sơ nhập giang hồ, Tam lưu, Nhị lưu, Nhất lưu, Tuyệt đỉnh, Tiên thiên cao thủ, Tông sư, Đại tông sư, Thiên nhân hợp nhất, Võ lâm chí tôn; chưa có điểm là Vô danh tiểu tốt.", "Dưới ấn cảnh giới có dòng “Cấp 20/100 · Đệ thập trọng”, số điểm còn thiếu để lên cấp kế tiếp, thanh tiến và thang 10 cảnh giới.", "Lên cấp hay đột phá cảnh giới đều có lời chúc mừng sau khi vận công; tắt được ở Cài đặt → Thông báo.", "Tâm pháp tu luyện có bảng thang 100 cấp: điểm mỗi cấp và tổng tu vi cần cho từng cảnh giới.", "Cấp tính theo tổng tu vi đã luyện nên không tụt khi đổi bảo vật; dữ liệu cũ giữ nguyên, chỉ cách tính cấp thay đổi."]},{version:'1.84.1',name:"Đổi Danh",title:"Bát phương đồ: đổi “An vui” thành “Tinh thần”",text:"Chỉ mục thứ tám trong Điểm tích lũy đổi tên từ “An vui” sang “Tinh thần”. Số điểm, cách tính và mã chỉ số giữ nguyên.",tags:["Điểm tích lũy", "chữ"],items:["Tên chỉ số thứ tám trên Bát phương đồ, trong danh sách Bát mạch tu vi, báo cáo tu luyện và thông báo: “An vui” → “Tinh thần”.", "Mô tả “Tiêu dao · sáng tạo · nghỉ ngơi” và các chỉ số khác giữ nguyên; không đổi dữ liệu, không migration."]},{version:'1.84.0',name:"Giang Hồ Hành",title:"Điểm tích lũy nói giọng giang hồ: ngôn ngữ Hán Việt và họa tiết kiếm hiệp",text:"Toàn bộ chữ trong mục Điểm tích lũy chuyển sang giọng giang hồ Hán Việt; khung, tiêu đề, nút và cảnh giới mang họa tiết kiếm hiệp: giấy dó, triện son, tường vân.",tags:["Điểm tích lũy", "giao diện"],items:["Tu vi, Bát phương đồ, Bát mạch tu vi, Công phu lục, Sổ bảo vật, Tâm pháp tu luyện; nút Đổi bảo vật, Đổi hiệp khách, Xem báo cáo tu luyện.", "Cảnh giới giang hồ: Vô danh tiểu tốt → Tam lưu, Nhị lưu, Nhất lưu, Tuyệt đỉnh cao thủ → Võ lâm chí tôn (cùng mốc điểm như cũ).", "Thế võ: Tùy hứng, Đàm tiếu, Luyện kiếm, Thái cực, Tọa thiền; hiệp khách xưng “tại hạ”, gọi người dùng là “các hạ”.", "Họa tiết: nền giấy dó, dấu triện son trước tiêu đề, tường vân ở góc khung, cảnh giới như ấn son, nút chính màu son; giao diện tối vẫn đủ tương phản."]},{version:'1.83.0',name:"Kiếm Ảnh",title:"Nhân vật kiếm hiệp và hoạt họa mới trong Điểm tích lũy",text:"Thiếu hiệp và nữ hiệp được vẽ lại theo phong cách kiếm hiệp Trung Hoa, đứng trên phông sơn thủy có mây trôi, sương, cành tùng và cánh đào rơi. Chuyển động mềm hơn, đổi tư thế chuyển dần không giật.",tags:["Điểm tích lũy", "giao diện"],items:["Thiếu hiệp: áo thanh lam, ngọc quan, tóc buộc dải lụa đỏ, kiếm sau lưng, quạt giấy, ngọc bội. Nữ hiệp: áo trắng khoác đỏ son, trâm bộ dao, lụa khoác, kiếm tua đỏ.", "Luyện kiếm có vệt kiếm khí; thái cực có đồ âm dương xoay; tọa thiền trên đá với khí tụ và hạt sáng bay lên.", "Tóc, dải lụa, tua kiếm, ngọc bội lay theo nhịp riêng; đổi tư thế hay lời thoại hiện dần, không vẽ lại cả trang.", "Bật “giảm chuyển động” thì nhân vật và phông đứng yên hoàn toàn."]},{version:'1.82.0',title:"Rà soát giao diện điện thoại, máy tính bảng, máy tính để bàn",text:"Kiểm tra lại toàn bộ màn hình chính ở 390, 820 và 1440 px, sửa các chỗ chưa vừa tay hoặc chưa gọn: lịch trên điện thoại, nút nhỏ trên màn hình cảm ứng, ô chọn giờ trong Cài đặt.",tags:["giao diện", "đa nền tảng"],items:["Lịch: hàng “Thứ 2…CN” không còn cao 150 px; trên điện thoại ô ngày thấp lại và mỗi việc chỉ hiện tối đa 3 dòng (tên đầy đủ vẫn đọc được ở “Lịch ngày” bên dưới).", "Màn hình cảm ứng (điện thoại, máy tính bảng): nút ghim ghi chú, thanh định dạng khi soạn, công tắc và ô chọn giờ trong Cài đặt, nút chọn chỉ số đều có vùng chạm từ 40 px.", "Máy tính để bàn dùng chuột giữ nguyên kích thước gọn như cũ; không đổi màu, vị trí hay dữ liệu."]},{version:'1.81.0',title:"Sử dụng điểm tích lũy",text:"Ghi lại vật phẩm đã mua hoặc quy đổi bằng điểm tích lũy; điểm được trừ khỏi biểu đồ chính, và có thể sửa, hủy hoặc khôi phục nếu nhập chưa đúng.",tags:["Điểm tích lũy"],items:["Nút “Sử dụng điểm” ở trang Điểm tích lũy mở form: tên vật phẩm, ngày, ghi chú và số điểm trừ ở từng chỉ số (hoặc nhập tổng rồi chia theo tỷ lệ điểm đang có).", "Điểm bị trừ ngay khỏi biểu đồ, các thanh chỉ số và ví điểm (hiện có · đã tích lũy · đã quy đổi); không cho quy đổi vượt số dư của từng chỉ số.", "Mục “Quy đổi điểm” liệt kê từng lần: Sửa để chỉnh lại, Hủy quy đổi để hoàn điểm (giữ dòng, có thể Khôi phục), Xóa hẳn với dòng đã hủy.", "Cảnh giới tính theo tổng điểm đã tích lũy nên không tụt khi bạn quy đổi."]},{version:'1.80.0',title:"Gom thông báo về một nhóm trong Cài đặt",text:"Cài đặt → Thông báo giờ gồm ba loại xếp dọc một cột: công việc, việc hằng ngày và điểm tích lũy, mỗi loại có công tắc riêng. Mỗi tuần có một gợi ý cải thiện trong chuông thông báo.",tags:["cài đặt", "thông báo"],items:["Công việc, việc hằng ngày, điểm tích lũy cùng nằm trong nhóm Thông báo; nút thông báo trình duyệt chuyển về đây", "Thông báo điểm nghiệp: báo điểm vừa cộng và khi nhân vật lên cảnh giới mới", "Gợi ý cải thiện hằng tuần dựa trên chỉ số đang thấp nhất, bấm vào để mở Báo cáo tiến độ"]},{version:'1.79.0',title:"Báo cáo tiến độ và thưởng điểm khi đủ 7 ngày",text:"Trong Điểm tích lũy có nút Xem báo cáo tiến độ: đánh giá 8 chỉ số mạnh yếu, độ cân bằng, đà 7 ngày qua và đề xuất cải thiện. Một việc hằng ngày đủ chuỗi 7 ngày liền cũng mở bảng cộng điểm.",tags:["tính năng mới", "tích lũy"],items:["Một việc hằng ngày đủ chuỗi 7, 14, 21… ngày liền: bảng cộng điểm 6 lần (3 điểm), mỗi mốc chỉ hỏi một lần", "Báo cáo tiến độ: tổng điểm, cảnh giới, 7 ngày qua so với 7 ngày trước, chuỗi ngày có cộng điểm", "Mỗi chỉ số được xếp Mạnh, Vững, Cần chăm hoặc Chưa bắt đầu; ba chỉ số thấp nhất kèm việc nên làm"]},{version:'1.78.0',title:"Điểm tích lũy: 8 chỉ số cuộc sống",text:"Chọn nhân vật nam hoặc nữ phong cách chibi cổ trang, rồi hoàn thành việc để bồi bổ 8 chỉ số: nghiệp quả, tài lộc, tâm cảnh, nhân duyên, thể lực, trí tuệ, sự nghiệp, an vui. Biểu đồ mạng nhện nối 8 điểm lại cho thấy bạn mạnh yếu ở đâu.",tags:["tính năng mới", "tích lũy"],items:["Mục Điểm tích lũy nằm ngay trên Phân bổ tài nguyên; nhân vật có 4 tư thế: cười nói, tập võ, đi quyền, ngồi thiền", "Hoàn thành một việc: bảng 8 cột hiện trước lời chúc mừng, mỗi lần bấm + thêm 0,5 điểm (tối đa 2 lần cho mỗi việc)", "Chưa chọn nhân vật thì mọi thứ im lặng, dữ liệu cũ không đổi; mỗi việc chỉ được cộng điểm một lần"]},{version:'1.77.0',title:"Thanh tab dự án gọn hơn",text:"Tên dự án dài không còn xuống 5–6 dòng làm thanh tab cao chiếm gần một phần năm màn hình điện thoại. Vẫn hiện đủ tên, không dùng dấu ba chấm.",tags:["giao diện", "điện thoại"],items:["Phần trăm tiến độ xuống dòng riêng nhỏ gọn dưới tên, tab rộng hơn một chút", "Thanh tab cao 109px thay vì 154px ở màn hình 390px; tên dài còn 3 dòng", "Chấm màu được bỏ vì viền trên của tab đã mang màu dự án"]},{version:'1.76.0',title:"Có hướng dẫn khôi phục dữ liệu",text:"Dữ liệu của bạn luôn được Cloudflare lưu lịch sử từng phút; bản này viết lại cách quay về một thời điểm trước đó nếu có sự cố. Ứng dụng không đổi gì với người dùng.",tags:["vận hành", "dữ liệu"],items:["Hướng dẫn từng bước khôi phục cơ sở dữ liệu về một phút bất kỳ trong 30 ngày (hoặc 7 ngày nếu gói miễn phí)", "Nói rõ những gì chưa được che: tệp đính kèm lưu riêng và chưa có bản sao lưu", "Chưa diễn tập khôi phục trên dữ liệu thật"]},{version:'1.75.0',title:"Đăng nhập an toàn hơn trước kẻ dò mật khẩu",text:"Người lạ gõ sai mật khẩu nhiều lần giờ chỉ tự chặn chính họ; bạn vẫn đăng nhập bình thường từ thiết bị của mình. Dò mật khẩu từ một nơi, nhiều email, hoặc nhiều nơi cùng lúc vẫn bị chặn.",tags:["bảo mật", "đăng nhập"],items:["Trước đây 10 mật khẩu sai từ bất kỳ đâu khóa đăng nhập của chính chủ 15 phút", "Giờ giới hạn theo từng cặp địa chỉ mạng và email; đăng nhập đúng thì xóa bộ đếm", "Có thêm trần dành cho tấn công từ nhiều nơi cùng lúc"]},{version:'1.74.0',title:"Phát hành ổn định hơn",text:"Quy trình kiểm tra trước khi phát hành tự thử lại khi mạng của GitHub chập chờn, để một sự cố mạng thoáng qua không còn làm chậm bản mới hàng giờ. Không đổi gì trong ứng dụng.",tags:["vận hành", "phát hành"],items:["Cài trình duyệt kiểm tra tự thử lại tối đa 4 lần", "Lưu đệm trình duyệt kiểm tra để bớt phụ thuộc mạng", "Không bỏ qua hay nới lỏng bất kỳ bài kiểm tra nào"]},{version:'1.73.0',title:"Theo dõi sức khỏe ứng dụng ẩn danh",text:"Ứng dụng giờ tự báo lỗi script và cho biết màn hình nào được mở, hoàn toàn ẩn danh, để lỗi được phát hiện sớm thay vì chờ bạn báo. Nếu email báo cáo hoặc nhắc việc gửi lỗi, Cài đặt sẽ cho bạn biết.",tags:["vận hành", "ẩn danh", "email"],items:["Chỉ gửi loại lỗi, nơi xảy ra và phiên bản; không kèm tên, email hay nội dung công việc", "Mỗi màn hình tối đa một dấu mỗi ngày; không gửi nếu trình duyệt bật Do Not Track hoặc Global Privacy Control", "Email báo cáo/nhắc việc gửi lỗi trong 3 ngày gần đây: có dòng báo ngay đầu Cài đặt"]},{version:'1.72.0',title:"Tổng quan gọn hơn, rõ việc cần làm",text:"Tổng quan không còn dành chỗ cho nhóm trống: khi hôm nay chưa có việc nào đến hạn, thẻ đó thu thành một dòng ở cuối, việc quá hạn lên đầu. Trên điện thoại, phần đầu trang ngắn hơn để thấy việc nhanh hơn.",tags:["tổng quan", "điện thoại", "gọn hơn"],items:["Hôm nay rỗng: thu thành một dòng, không còn thẻ cao trống", "Phần không có việc chỉ còn một dòng chữ, bỏ nút mở danh sách trống", "Điện thoại: lời chào và nút Tạo dự án trong một khối thấp, tên dự án không bẻ nhiều dòng"]},{version:'1.71.0',title:"Chuyển màn hình nhanh hơn",text:"Khi có hàng trăm việc, chuyển giữa Tổng quan, Dự án, Lịch và các màn hình khác nhanh hơn rõ rệt; mở ứng dụng cũng nhẹ hơn. Không đổi giao diện, không đổi dữ liệu.",tags:["hiệu năng","nhanh hơn"],items:["Tổng quan với khoảng 1.000 việc: từ khoảng 0,7 giây còn khoảng 0,05 giây khi chuyển sang","Mở ứng dụng với nhiều dự án nhẹ hơn nhiều lần","Máy chủ xử lý nhanh hơn khi lưu dữ liệu lớn (hàng nghìn việc)"]},{version:'1.70.0',title:"Biểu đồ hòa vốn",text:"Phân bổ tài nguyên có thêm biểu đồ thứ ba: tiền chi và tiền thu hồi cộng dồn theo thời gian trên cùng một biểu đồ, để thấy dự án đã hòa vốn chưa và còn thiếu bao nhiêu.",tags:["đầu tư","biểu đồ","hòa vốn"],items:["Hai đường cộng dồn trên một trục thời gian: chi và thu hồi; vùng xanh là phần đã thu hồi","Đang lỗ: có đường mốc hòa vốn và số tiền còn thiếu; đã hòa vốn: có điểm hòa vốn và ngày bắt đầu","Có ở tổng quan (tất cả dự án) và trong từng dự án; cập nhật ngay khi thêm khoản thu chi"]},{version:'1.69.0',title:"Phân bổ tài nguyên: quay lại dễ hơn, dashboard rõ hơn",text:"Vào từng dự án giờ có nút quay lại về tất cả dự án, nút Back của điện thoại cũng hoạt động. Dashboard thu chi có thêm dòng tiền 6 tháng, thanh lãi/lỗ từng dự án và các điểm nổi bật.",tags:["đầu tư","điều hướng","thống kê"],items:["Nút Tất cả dự án ở đầu và cuối trang dự án; nút Back, ô chọn dự án và mục menu đều đưa về tổng quan, giữ nguyên vị trí cuộn","Biểu đồ dòng tiền 6 tháng gần nhất: cột chi, cột thu và lãi/lỗ ròng từng tháng","Thanh lãi/lỗ cho từng dự án; sắp xếp theo lỗ nhiều nhất, lãi nhiều nhất hoặc chi nhiều nhất","Điểm nổi bật: dự án lỗ/lãi nhiều nhất, tháng này, hạng mục chi lớn nhất; lọc các khoản theo Chi hoặc Thu"]},{version:'1.68.0',title:"Chia sẻ báo cáo thu chi bằng link",text:"Báo cáo thu chi tuần giờ có thể gửi cho người khác bằng link xem trên web: đặt mật khẩu, chọn thời hạn, thu hồi bất cứ lúc nào, giống báo cáo công việc.",tags:["đầu tư","chia sẻ","báo cáo"],items:["Cài đặt → Báo cáo thu chi tuần: nút Xuất link chia sẻ; trong bản xem trước có nút Chia sẻ web","Mặc định có mật khẩu vì báo cáo có số tiền; vẫn có thể chọn công khai qua link","Link giữ nguyên số liệu tại lúc tạo; thời hạn từ 1 đến 30 ngày; thu hồi trong danh sách link đang hoạt động","Trang xem chỉ đọc, có nút In / Lưu PDF, không lộ việc hay ghi chú riêng"]},{version:'1.67.0',title:"Báo cáo email thu chi hằng tuần",text:"Mỗi tuần nhận một email tổng hợp thu chi của các dự án: đã chi, đã thu hồi, lãi/lỗ và dự án nào đang lỗ nhiều nhất. Bật hoặc tắt trong Cài đặt, chọn ngày và giờ gửi.",tags:["đầu tư","email","cài đặt"],items:["Cài đặt → Báo cáo thu chi tuần: bật/tắt, chọn thứ trong tuần và giờ gửi (giờ Việt Nam); mặc định tắt","Email cùng kiểu với email tổng kết công việc: biểu đồ tròn, thanh phân bổ, bảng số liệu từng dự án","Chỉ gửi khi đã có ít nhất một khoản thu chi; nút Xem báo cáo & PDF để xem thử ngay","Nút Báo cáo email hằng tuần ở trang Phân bổ tài nguyên mở thẳng phần cài đặt này"]},{version:'1.66.0',title:"Phân bổ tài nguyên: thu chi từng dự án",text:"Mục mới \"Phân bổ tài nguyên\" thay cho \"Tất cả công việc\": ghi khoản thu và khoản chi cho từng dự án, xem biểu đồ tròn theo hạng mục và biết dự án đang lãi hay lỗ. Ô tìm kiếm vẫn cho kết quả gọn.",tags:["đầu tư","dự án","giao diện"],items:["Trong dự án: nút Chi, nút Thu, nhập số tiền, hạng mục, ngày và ghi chú; sửa hoặc xóa có xác nhận","Biểu đồ tròn theo hạng mục cho riêng khoản chi hoặc khoản thu","Tổng quan mọi dự án: đã chi, đã thu hồi, lãi/lỗ và tỉ lệ thu hồi; dự án lỗ nhiều nhất xếp đầu","Gỡ trang Tất cả công việc cùng bộ lọc, chọn nhiều việc và nút việc mới của trang đó"]},{version:'1.65.0',title:"Gọn hơn: khung tùy chọn, hộp công việc, ô hôm nay",text:"Thu nhỏ khung Đồng bộ / Giao diện tối / Thông báo; hộp chi tiết công việc gọn và rõ hơn; sửa ô hôm nay của Việc hằng ngày bị lệch thấp hơn các ngày khác trên điện thoại và máy tính bảng.",tags:["giao diện","công việc","việc hằng ngày"],items:["Khung tùy chọn nhanh hẹp hơn, mỗi hàng thấp hơn nhưng nút vẫn bấm dễ","Hộp công việc: hàng tiêu đề một dòng, trạng thái lưu là viên nhỏ, mức độ xếp 2×2, bỏ dòng hướng dẫn lặp","Việc hằng ngày: vòng tròn hôm nay thẳng hàng với các ngày khác"]},{version:'1.64.0',title:"Kho câu: đủ 2.222 câu, thêm 110 lời Thiền sư Đường–Tống",text:"Thêm 110 lời của Mã Tổ, Bách Trượng, Nam Tuyền, Đại Châu Huệ Hải, Thạch Đầu, Dược Sơn, Động Sơn, Đức Sơn, Nham Đầu, Tuyết Phong, Vân Môn và Hoàng Bá. Tất cả đối chiếu nguyên văn Hán với Ngũ Đăng Hội Nguyên (CBETA). Kho câu đạt mục tiêu 2.222.",tags:["lời chào","kho câu","thiền sư"],items:["Bách Trượng 13, Mã Tổ 8, Thạch Đầu 9, Vân Môn 8, Dược Sơn 6, Động Sơn 5, Nam Tuyền 15, Đại Châu 18, Hoàng Bá 7, Đức Sơn 7, Nham Đầu 8, Tuyết Phong 6","Mỗi câu giữ nguyên văn Hán, bản dịch nghĩa tiếng Việt, tên sách và đường dẫn nguồn","Bản dịch tiếng Việt là bản dịch nghĩa, chưa thẩm định chuyên gia"]},{version:'1.63.0',title:"Kho câu: thêm 161 lời thiền sư xưa, lên 2.112 câu",text:"Thêm lời của Nhị tổ Huệ Khả, Lục tổ Huệ Năng, Tam tổ Tăng Xán, Bồ Đề Đạt Ma, Huyền Giác, Hoàng Bá, Lâm Tế, Vô Môn và vua Trần Nhân Tông. 155 câu được đối chiếu nguyên văn Hán với Đại Chính tạng; 6 câu Trần Nhân Tông ghi chú là tham khảo.",tags:["lời chào","kho câu","thiền sư"],items:["Huệ Năng 34, Huyền Giác 33, Tăng Xán 25, Hoàng Bá 19, Lâm Tế 19, Huệ Khả 16, Đạt Ma 8, Vô Môn 1, Trần Nhân Tông 6","Mỗi câu giữ nguyên văn Hán, bản dịch nghĩa tiếng Việt, tên kinh và đường dẫn nguồn","Bản dịch tiếng Việt là bản dịch nghĩa, chưa thẩm định chuyên gia"]},{version:'1.62.0',title:"Kho câu: thêm 374 câu từ nguồn công khai cho 11 tác giả, lên 1.951 câu",text:"Thêm 374 câu cho Lục tổ Huệ Năng, Hàn Sơn, Long Thọ, Plotinus, Rumi, Socrates, Krishnamurti, Hakuin, Adi Shankara, Phanxicô thành Assisi và Trần Nhân Tông. Phần lớn được đối chiếu nguyên văn với bản công khai; 4 câu Trần Nhân Tông ghi chú là tham khảo.",tags:["lời chào","kho câu","nguồn"],items:["Huệ Năng 100, Hàn Sơn 86, Long Thọ 66, Plotinus 30, Rumi 28, Socrates 22, Krishnamurti 11, Hakuin 10, Adi Shankara 9, Phanxicô 8, Trần Nhân Tông 4","Chỉ Huệ Năng đạt 100 câu mới; Liên Hoa Sinh, Milarepa và Đạo Nguyên chưa có câu mới","Bản dịch tiếng Việt là bản dịch nghĩa, chưa thẩm định chuyên gia"]},{version:'1.61.0',title:"Kho câu: thêm 51 câu tham khảo cho 11 tác giả mới, lên 1.577 câu",text:"Thêm 51 câu từ trang bên thứ ba có ghi nguồn cho Socrates, Plotinus, Meister Eckhart, Phanxicô thành Assisi, Hàn Sơn, Long Thọ, Huệ Năng, Ramana Maharshi, Krishnamurti, Trần Nhân Tông và vài tác giả khác. Tất cả được ghi chú là tham khảo.",tags:["lời chào","kho câu","tham khảo"],items:["Socrates 6, Krishnamurti 8, Meister Eckhart 6, Plotinus 6, Huệ Năng 6, Ramana Maharshi 6, Hàn Sơn 4, Phanxicô 3, Trần Nhân Tông 2, Long Thọ, Rumi, Deepak Chopra, Hakuin mỗi người 1", "Chưa đạt 100 câu cho mỗi tác giả: công cụ chỉ đọc được trích đoạn từ web, không tải được sách nguyên văn", "Chưa có câu mới cho Adi Shankara, Liên Hoa Sinh, Milarepa, Đạo Nguyên và Thích Nhất Hạnh", "Không đổi giao diện, logic chọn câu hay mục tiêu 2.222 câu"]},{version:'1.60.0',title:"Kho câu: thêm 166 câu có nguồn, lên 1.526 câu",text:"Thêm 166 câu có nguồn từ các tệp nguyên văn trong kho. Mỗi câu đối chiếu được với tệp nguồn; mục tiêu 2.222 câu không đổi.",tags:["lời chào", "kho câu", "nguồn"],items:["Trang Tử: thêm 100 câu từ bản dịch Giles của Nam Hoa Kinh", "Khổng Tử: thêm 20 câu Luận Ngữ, bản Legge", "Upanishad, Bhagavad Gita, Kabir, Mạnh Tử, Tuân Tử: thêm 46 câu", "Chưa đạt 100 câu cho mỗi tác giả: nguồn trong kho không đủ cho các tác giả còn lại; không thêm câu chưa đối chiếu được"]},{version:'1.59.1',title:'Ghi chú nguồn: câu chưa có nguồn chính thức là tham khảo',text:'Kho Osho giữ 111 câu có nguồn. Các câu đối chiếu trên trang bên thứ ba và câu Dōgen được ghi chú là tham khảo.',tags:['lời chào','Osho','nguồn'],items:['Đánh dấu tham khảo cho 20 câu Osho đối chiếu trên quotewise.io hoặc thư viện Overdrive, chưa có nguồn chính thức','Đánh dấu tham khảo cho câu Dōgen, chưa có nguồn xác thực; giữ nguyên theo yêu cầu','Gợi ý chiêm nghiệm ghi rõ là không phải lời trích','Không đổi nội dung câu, bản dịch, liên kết hay thứ tự ưu tiên']},{version:'1.59.0',title:'Kho Osho: thêm 78 câu có nguyên văn, lên 111 câu',text:'Kho Osho có 111 câu có nguồn, thêm 78 câu có nguyên văn tiếng Anh hiển thị trên oshonews.com. Mỗi câu có liên kết tới trang gốc. Gợi ý chiêm nghiệm và câu Dōgen giữ nguyên.',tags:['lời chào','Osho','nguồn'],items:['Thêm 78 câu Osho có nguyên văn tiếng Anh, đưa kho Osho lên 111 câu có nguồn','Mỗi câu có liên kết tới bài gốc trên oshonews.com và bản dịch tiếng Việt khớp với câu gốc','Đối chiếu qua trang chuyên mục và thẻ của oshonews.com; chưa mở được từng bài gốc trong lần này','Gợi ý chiêm nghiệm và câu Dōgen giữ nguyên theo yêu cầu','Thứ tự ưu tiên Osho giữ nguyên']},{version:'1.58.0',title:'Kho Osho: chỉ giữ câu có nguyên văn đã kiểm chứng',text:'Gỡ 79 câu Osho chưa tìm được nguyên văn tiếng Anh. Kho còn 33 câu Osho có nguồn đã đối chiếu, cộng một gợi ý chiêm nghiệm không phải lời trích.',tags:['lời chào','Osho','nguồn'],items:['Gỡ 79 câu Osho chưa tìm được nguyên văn tiếng Anh trên trang trích dẫn hoặc oshonews.com','Giữ 26 câu cũ có nguyên văn; sửa bản dịch cho khớp, nhiều câu chỉ giữ phần đã kiểm chứng','Kho còn 33 câu Osho có nguồn đã đối chiếu, cộng 1 gợi ý chiêm nghiệm được ghi rõ là không phải lời trích','Đối chiếu qua trang trích dẫn bên thứ ba và oshonews.com; chưa đối chiếu bản in của sách','Thứ tự ưu tiên Osho giữ nguyên']},{version:'1.57.0',title:'Kho Osho: bỏ câu chưa kiểm chứng, thêm 7 câu có nguồn',text:'Bỏ 6 câu Osho chưa kiểm chứng được nguồn, thêm 7 câu Osho có nguồn đã đối chiếu trên oshonews.com. Kho có 112 câu Osho; phần còn lại vẫn là bản dịch nghĩa, chưa đối chiếu nguyên văn.',tags:['lời chào','Osho','nguồn'],items:['Bỏ 6 câu Osho biên soạn chưa có nguồn đã kiểm chứng','Thêm 7 câu Osho có nguyên văn trên oshonews.com, ghi rõ sách và chương','Kho có 112 câu Osho; 105 câu cũ vẫn ghi là bản dịch nghĩa, chưa đối chiếu nguyên văn','Ưu tiên hiển thị Osho ở nửa đầu chu kỳ giữ nguyên']},{version:'1.56.0',title:'Gom tùy chọn nhanh vào một dropdown, đưa tìm kiếm về giữa',text:'Đồng bộ, giao diện tối và thông báo gom vào một nút Tùy chọn nhanh có biểu tượng nhận biết. Ô tìm kiếm nằm giữa thanh công cụ ở mọi kích thước màn hình.',tags:['thanh công cụ','dropdown','tìm kiếm','giao diện'],items:['Đồng bộ, giao diện tối và thông báo gom vào dropdown Tùy chọn nhanh','Chấm đỏ trên nút khi có thông báo cần xem','Ô tìm kiếm căn giữa thanh công cụ ở 390, 820 và 1440 px','Mở và đóng bằng bấm, phím Escape hoặc bấm ra ngoài']},{version:'1.55.2',title:'Ô thêm việc mới gọn hơn trong checklist',text:'Ô nhập việc mới hiển thị trên một dòng, placeholder ngắn gọn, nút Thêm căn giữa và gợi ý rút gọn để không xuống dòng trên điện thoại.',tags:['checklist','giao diện','responsive'],items:['Placeholder rút gọn: Thêm việc cần làm…','Ô nhập và nút Thêm cùng một dòng, căn giữa theo chiều dọc','Gợi ý phím tắt rút gọn, không còn xuống dòng trên 390 px']},{version:'1.55.1',title:'Căn lề checklist theo một trục, sửa lỗi kiểm tra vùng chạm',text:'Tay kéo, ô tick và nút × nay căn thẳng hàng với dòng chữ đầu của mỗi mục. Vùng chạm cảm ứng đủ 44px, ô nội dung rộng hơn trên điện thoại. Bản này gom các thay đổi 1.53.0 đến 1.55.0, vốn chưa được phát hành do bài kiểm tra CI không đạt.',tags:['checklist','căn lề','responsive','cảm ứng'],items:['Tay kéo, ô tick và nút × căn giữa theo dòng chữ đầu tiên của mục','Lưới 4 cột cố định, ô nội dung rộng hơn trên điện thoại','Vùng chạm 44px cho tay kéo và nút × khi dùng cảm ứng; chuột dùng kích thước gọn hơn','Nhật ký phiên bản 1.53.0 đến 1.55.0 có đủ ghi chú và từ khóa']},{version:'1.55.0',title:'Căn lề checklist theo một trục',text:'Tay kéo, ô tick và nút × cùng căn theo dòng chữ đầu; lưới 4 cột thay cho các lưới chồng nhau cũ. Bản phát hành này chưa được triển khai do kiểm tra vùng chạm cảm ứng chưa đạt, được sửa ở 1.55.1.',tags:['checklist','căn lề'],items:['Căn giữa tay kéo, ô tick và nút × với dòng chữ đầu','Xóa các quy tắc lưới chồng nhau và khối cảm ứng gây lệch','Giảm số khai báo !important từ 832 xuống 829']},{version:'1.54.0',title:'Hoàn thành 111 câu nói Osho',text:'Kho lời chào có đủ 111 câu Osho Việt hóa. Bản này chưa được triển khai do bài kiểm tra nhật ký phiên bản chưa đạt, được sửa ở 1.55.1.',tags:['lời chào','Osho','nguồn'],items:['Thêm 6 câu Osho Việt hóa, tổng 111 câu trong kho','Kho có 1.360 trích đoạn có nguồn']},{version:'1.53.0',title:'Sửa lỗi lệch khung checklist',text:'Lần sửa đầu tiên cho lỗi lệch khung checklist. Chưa triệt để và được thay thế bởi 1.55.0.',tags:['checklist'],items:['Khôi phục khoảng cách trên của ô tick so với nội dung','Bỏ một phần quy tắc lưới chồng nhau']},{version:'1.52.0',title:'Mở rộng Quỷ Cốc Tử lên 30 câu, thêm ~100 câu Osho',text:'Kho lời chào có thêm 16 câu Quỷ Cốc Tử (tổng 30 câu có nguồn) và ~97 câu triết học tỉnh thức từ Osho, Việt hóa toàn bộ. Osho ưu tiên hiển thị nhiều hơn trong vòng xoay.',tags:['lời chào','Quỷ Cốc Tử','Osho','nguồn','tỉnh thức'],items:['Mở rộng Quỷ Cốc Tử từ 14 lên 30 câu có nguồn từ tệp nguồn tiếng Việt','Thêm ~97 câu Osho Việt hóa hoàn toàn vào kho lời chào','Osho được ưu tiên hiển thị trước trong chu kỳ xoay vòng','Lời chào vẫn xoay vòng, không lặp trong một chu kỳ']},{version:'1.51.0',title:'Thêm 14 câu Quỷ Cốc Tử vào kho lời chào',text:'Kho lời chào có thêm 14 câu ngắn từ Quỷ Cốc Tử, bản dịch tiếng Việt của Nguyễn Lư. Mỗi câu ghi rõ điều và chương trong sách.',tags:['lời chào','Quỷ Cốc Tử','nguồn'],items:['Thêm 14 trích đoạn có nguồn từ Quỷ Cốc Tử, đối chiếu với tệp nguồn trước khi nạp','Mỗi câu ghi rõ điều và chương trong sách','Lời chào vẫn xoay vòng, không lặp trong một chu kỳ']},{version:'1.50.1',title:'Khung ô hôm nay không còn đè lên ngày bên cạnh',text:'Khung đánh dấu ngày hôm nay trong việc hằng ngày chỉ cao thêm, đúng bề rộng cột, không chồng lên vòng tròn của ngày kế bên.',tags:['việc hằng ngày','khung hôm nay','canh lề','giao diện'],items:['Khung ô hôm nay đúng bề rộng cột, không đè lên vòng tròn T2 hoặc T4','Khung vẫn bao trọn nhãn ngày và vòng tròn của hôm nay','Không đổi dữ liệu hay cách đánh dấu việc']},{version:'1.50.0',title:'Checklist gọn, không còn %; thanh trên gom một chỗ',text:'Checklist chỉ hiện nội dung và số mục đã xong. Thanh trên có một cụm nút bên phải và ô tìm kiếm ở giữa.',tags:['checklist','phần trăm','thanh trên','tìm kiếm','giao diện'],items:['Bỏ ô % và chữ % ở từng mục checklist; nội dung chiếm trọn dòng','Bỏ con số % trong tiêu đề tiến độ checklist, giữ số mục đã xong (ví dụ 2/5 mục đã hoàn thành)','Thanh trên: ô tìm kiếm ở giữa; trạng thái lưu, sáng/tối, chuông và avatar gom một cụm bên phải','Trên điện thoại: nút ☰, tìm kiếm và cụm nút nằm trên một hàng']},{version:'1.49.0',title:'Dán nhiều dòng vào ghi chú không còn chồng dòng',text:'Dán hoặc gõ nhiều dòng vào card ghi chú giờ hiện đủ từng dòng, không còn chồng lên nhau.',tags:['ghi chú','dán','xuống dòng','giao diện'],items:['Dán nhiều dòng vào card ghi chú không còn chồng dòng','Gõ nhiều dòng trong ghi chú cũng hiển thị rõ từng dòng','Dòng trống khi dán giữ khoảng cách gọn như cũ']},{version:'1.48.0',title:'Đường nối Gantt mềm mại, kéo để đổi đường đi',text:'Đường nối giữa các công việc trên Gantt đi theo góc bo tròn; kéo tay nắm giữa đường để đổi đường đi theo ý bạn.',tags:['gantt','đường nối','mũi tên','kéo thả','giao diện'],items:['Đường nối mềm mại hơn, đi theo góc bo tròn thay cho đường cong cũ','Kéo tay nắm giữa đường nối để đổi đường đi; dùng được bằng chuột, ngón tay hoặc phím mũi tên','Vị trí đường đi giữ nguyên khi đổi khoảng xem 7, 15 hoặc 30 ngày']},{version:'1.47.1',title:'Tên tab dự án dài hiện đủ, không bị cắt',text:'Tên dự án dài trên dải tab xuống dòng và canh giữa trong khung; khung giữ nguyên chiều rộng và chỉ cao thêm khi cần đủ dòng.',tags:['tab dự án','tràn chữ','xuống dòng','canh giữa','giao diện'],items:['Tên dự án dài xuống dòng trong khung tab, không bị cắt chữ','Khung tab giữ nguyên chiều rộng, viền và bo góc','Phần trăm tiến độ luôn nằm một dòng cuối tab','Khi tab cao thêm, ô đang lấy nét không bị khung dính che khi cuộn']},{version:'1.46.0',title:'Việc đã xong tự gỡ khỏi khu ghim',text:'Khi một việc đã hoàn thành, việc đó tự được gỡ ghim khỏi mục "Ghim công việc" ở thanh bên. Thanh bên chỉ còn việc đang mở, gọn và ít rối mắt hơn.',tags:['ghim','thanh bên','hoàn thành','gọn','việc đang mở'],items:['Việc đã ở cột Xong sẽ tự bỏ ghim khi lưu','Việc vừa hoàn thành rời khỏi khu ghim ngay','Việc đang mở vẫn giữ ghim; ghim và bỏ ghim thủ công vẫn dùng được']},{version:'1.45.0',title:'Lời chúc lớn khi gỡ hết việc quá hạn hoặc hoàn tất dự án',text:'Khi việc quá hạn cuối cùng được xong, hoặc mọi việc của một dự án đã hoàn tất, lời chúc hiện khung rộng có icon và họa tiết.',tags:['chúc mừng','hoàn thành','quá hạn','dự án','lời chúc','icon'],items:['Gỡ hết việc quá hạn: hiện lời chúc riêng, khung rộng hơn','Hoàn tất mọi việc của một dự án: lời chúc riêng cho dự án','Có 30 lời chúc mới, mỗi lần một câu khác','Nút đóng đủ lớn để chạm trên điện thoại']},{version:'1.44.0',title:'Chữ gõ không bị đổi định dạng khi mở lại',text:'Các ký tự như *, __, #, dấu gạch đầu dòng hay số kèm dấu chấm được giữ nguyên là chữ thường trong mô tả việc, dự án và ghi chú.',tags:['định dạng','ghi chú','mô tả','soạn thảo','ký tự','lỗi'],items:['Gõ "5 * 3 * 2" không còn bị in nghiêng khi mở lại','Gõ "__tên__" hoặc "# tiêu đề" như chữ thường không bị gạch chân hay thành tiêu đề','In đậm kèm khoảng trắng ở cuối vẫn giữ đúng định dạng']},{version:'1.43.0',title:'Chọn giờ nhắc việc hằng ngày dễ hơn',text:'Giờ nhắc có nút gợi ý nhanh và hai ô giờ, phút thay cho ô giờ của trình duyệt.',tags:['nhắc lúc','giờ nhắc','việc hằng ngày','chọn giờ','không nhắc'],items:['Nút gợi ý nhanh: 7:00, 12:00, 18:00, 21:00','Chọn giờ và phút bằng hai ô, phút theo bước 5','Nút "Không nhắc" xóa giờ nhắc của việc','Dòng trạng thái cho biết việc sẽ được nhắc lúc mấy giờ']},{version:'1.42.0',title:'Ô % gọn ngay cuối dòng checklist',text:'Bỏ thanh kéo tiến độ cho gọn. Mỗi mục giờ gồm ô đánh dấu, nội dung và số % in đậm cuối dòng; gõ số trực tiếp.',tags:['checklist','phần trăm','tiến độ','ô số','gọn','mục'],items:['Thanh kéo tiến độ được thay bằng ô số nhỏ cuối mỗi dòng checklist','Gõ số từ 0 đến 100; số lớn hơn 100 tự về 100','Tick mục đưa về 100%, bỏ tick đưa về 0%','Chế độ tập trung dùng cùng ô số']},{version:'1.41.0',title:'Lời nhắc nhẹ khi hôm nay chưa có việc nào được tích',text:'Một dòng gợi ý nhẹ mở đầu ngày. Hiện ở tuần hiện tại, đóng một lần là thôi đến hết ngày.',tags:['nhắc việc','lời nhắc','chưa tích','hôm nay','việc hằng ngày','gợi ý'],items:['Hiện lời nhắc nhẹ khi hôm nay chưa tích việc nào, ở tuần hiện tại','Bấm Đóng thì ẩn đến hết ngày; tích một việc thì ẩn ngay','Không hiện khi mọi việc đều nghỉ hôm nay']},{version:'1.40.0',title:'Báo cáo riêng cho từng việc hằng ngày',text:'Xem lịch sử của một việc với tỷ lệ, chuỗi dài nhất và ghi chú trong 28 hoặc 90 ngày.',tags:['lịch sử','báo cáo','xem lịch sử','tỷ lệ','chuỗi','việc hằng ngày'],items:['Nút Xem lịch sử bằng chữ ở dòng cuối của từng việc, thay biểu tượng cũ','Báo cáo riêng của việc: chọn xem 28 hoặc 90 ngày','Hiện tỷ lệ hoàn thành (không tính ngày nghỉ) và chuỗi dài nhất trong khoảng đã chọn','Ghi chú cảm nhận hiện trong báo cáo']},{version:'1.39.0',title:'Kéo để đổi thứ tự việc hằng ngày',text:'Sắp xếp việc quan trọng lên đầu bằng cách kéo tay cầm. Thứ tự được đồng bộ giữa các thiết bị.',tags:['đổi thứ tự','kéo thả','việc hằng ngày','tay cầm','sắp xếp','thứ tự'],items:['Kéo tay cầm (sáu chấm) để đổi thứ tự việc hằng ngày, bằng chuột hoặc cảm ứng','Trên bàn phím: chọn tay cầm rồi nhấn mũi tên lên hoặc xuống','Thứ tự được lưu và đồng bộ giữa các thiết bị']},{version:'1.38.0',title:'Ghi chú cảm nhận theo từng ngày',text:'Giữ một ô ngày để ghi lại cảm nhận ngay tại chỗ. Ghi chú được đồng bộ giữa các thiết bị.',tags:['ghi chú','ghi chú cảm nhận','giữ ô','chuột phải','Shift+Enter','lịch sử'],items:['Giữ một ô ngày (0,5 giây) để ghi chú cảm nhận cho ngày đó; trên máy tính: chuột phải hoặc Shift+Enter','Ô đã có ghi chú hiện chấm tím; lịch sử 28 ngày liệt kê ghi chú','Để trống rồi lưu để xóa ghi chú; tối đa 140 ký tự']},{version:'1.37.0',title:'Sửa tràn ngang khi tích việc hằng ngày trên máy tính bảng',text:'Việc hằng ngày không còn tràn ngang ở 820 px khi tích việc. Không đổi dữ liệu hay chức năng.',tags:['việc hằng ngày','máy tính bảng','820','bố cục','tràn ngang','tiến độ'],items:['Việc hằng ngày không còn tràn ngang trên máy tính bảng 820 px khi tích việc','Phần trăm tiến độ tuần được xuống dòng thay vì bị đẩy ra ngoài màn hình','Thêm kiểm thử ở 390, 820 và 1440 px cho trường hợp này']},{version:'1.36.0',title:'Thanh chuyển chế độ không còn lộ nội dung khi cuộn',text:'Trên điện thoại, thanh Bảng Kanban, Lịch, Gantt khi cuộn có nền đặc, không còn để lộ tên việc và các ô tròn bên dưới.',tags:['Việc hằng ngày','Bố cục điện thoại'],items:['Thanh chuyển chế độ (Bảng Kanban, Lịch, Gantt) dính trên đầu khi cuộn trên điện thoại giờ có nền đặc.','Trước đây nền thanh trong suốt 3%, nên tên việc và các ô tròn bên dưới lộ qua khi cuộn.','Áp dụng cho cả chế độ sáng và chế độ tối.']},{version:'1.35.0',title:'Sửa nút Làm mới (đồng bộ) ở Chế độ tập trung',text:'Nút Làm mới ở Chế độ tập trung hiển thị đúng trên điện thoại: biểu tượng và chữ nằm gọn trong nút, không còn lệch hay tràn.',tags:['Đồng bộ','Chế độ tập trung'],items:['Nút “Làm mới” ở Chế độ tập trung (kiểm tra dữ liệu mới từ máy chủ) hiển thị đúng trên điện thoại: biểu tượng và chữ nằm gọn trong nút.','Trước đây nút bị ép thành ô vuông 44 px: chữ “Làm mới” tràn ra ngoài và biểu tượng lệch khỏi nền tím.','Nguyên nhân: hai bộ quy tắc CSS của hai thời điểm thiết kế đè lên nhau. Đã bỏ quy tắc cũ, giữ kiểu có nhãn chữ cho mọi trang.','Nút không còn đổi sang nền trắng khi rê chuột, nên chữ luôn đọc được.','Bấm nút vẫn hoạt động như cũ: tải dữ liệu mới nhất, hoặc báo lý do chưa làm mới được.']},{version:'1.34.0',title:'Giờ nhắc riêng cho từng việc hằng ngày',text:'Mỗi việc hằng ngày giờ có thể đặt giờ nhắc riêng. Đến giờ và chưa làm, việc sẽ hiện ở đầu trang Việc hằng ngày và trong chuông thông báo.',tags:['Việc hằng ngày','Nhắc việc'],items:['Nhắc lúc: ô giờ (theo đồng hồ 24 giờ) trong biểu mẫu Thêm hoặc Sửa việc hằng ngày. Để trống thì việc đó không được nhắc.','Giờ nhắc tính theo giờ Việt Nam, cùng múi giờ với ngày trong ứng dụng.','Khi đến giờ nhắc, việc chưa làm và chưa nghỉ hôm nay hiện trong khung “đến giờ nhắc” ở đầu trang Việc hằng ngày, kèm nút “Đã xem”.','Việc đã làm hoặc đã đánh dấu nghỉ hôm nay không được nhắc.','Mỗi dòng việc có dấu “Nhắc 07:30” để thấy giờ nhắc ngay.','Chuông thông báo hiện chấm và nêu tên việc đến giờ nhắc. Số việc quá hạn trên chuông không đổi, vì nhắc việc không tính là việc quá hạn.','Bấm một mục trong hộp thoại Thông báo để mở đúng trang Việc hằng ngày.','“Đã xem” tắt nhắc của việc đó đến hết ngày, hoặc đến khi đổi giờ nhắc. Trạng thái này lưu trên trình duyệt đang dùng.','Trang tự hiện khung nhắc khi đến giờ, không cần tải lại; không tự cập nhật khi đang mở biểu mẫu.','Dữ liệu: thêm trường giờ nhắc (không bắt buộc, dạng HH:MM) cho từng việc. Việc cũ không có trường này vẫn hoạt động như trước; đồng bộ theo từng việc như các trường khác.','Máy chủ chỉ nhận giờ đúng dạng HH:MM và từ chối giờ sai, ví dụ 7:30, 25:00 hoặc 07:60.']},{version:'1.33.0',title:'Nghỉ hôm nay và lịch sử từng việc',text:'Ngày nghỉ không làm đứt chuỗi; mỗi việc có lịch sử 28 ngày gần nhất ngay trên thẻ.',tags:['Việc hằng ngày','Tính năng'],items:['Nghỉ hôm nay: đánh dấu ngày nghỉ khi chưa làm việc đó; ngày nghỉ không làm đứt chuỗi và không được tính là đã làm.','Lịch sử: nút trên từng việc mở 28 ngày gần nhất (đã làm, nghỉ, chưa làm) và chuỗi hiện tại.','Máy chủ và ứng dụng chấp nhận trường nghỉ mới (tùy chọn; dữ liệu cũ không đổi).']},{version:'1.32.0',title:'Việc hằng ngày gọn và dễ bấm trên điện thoại',text:'Nút Lưu luôn nhìn thấy, tên việc gọn, biểu tượng dễ chọn trên điện thoại; ghi chú tiến độ rõ hơn.',tags:['Việc hằng ngày','Giao diện'],items:['Nút Lưu và Hủy luôn nhìn thấy ở cuối hộp thoại trên điện thoại.','Tên việc dài tối đa 2 dòng; biểu tượng xếp 4 cột trên điện thoại.','Ghi chú tiến độ gọn hơn: Còn X lượt cần làm · đã làm Y/Z.','Bỏ dòng tiêu đề lặp; nhãn Chưa gắn dự án nhạt hơn.']},{version:'1.31.0',title:'Nhật ký phiên bản rõ từng bản',text:'Mỗi phiên bản là một khung riêng, có từ khóa hạng mục đã cải thiện và nội dung chi tiết hơn.',tags:['Giao diện','Nhật ký'],items:['Nhật ký phiên bản: mỗi phiên bản là một khung riêng.','Mỗi khung có từ khóa cho biết hạng mục đã cải thiện (ví dụ Đồng bộ, Bảo mật).','Chi tiết hơn cho các bản 1.25.0 đến 1.30.0.','Gỡ thẻ tóm tắt cứng trên Tổng quan đang hiển thị sai nội dung.']},{version:'1.30.0',title:'Bỏ nút đăng xuất mọi thiết bị',text:'Phần Phiên đăng nhập trong Cài đặt không còn nút Đăng xuất mọi thiết bị. Nút Đăng xuất của máy này vẫn giữ nguyên.',tags:['Bảo mật','Đăng nhập'],items:['Bỏ nút "Đăng xuất mọi thiết bị" trong Cài đặt.','Nút "Đăng xuất" của máy này giữ nguyên.','Máy chủ và dữ liệu không đổi.']},{version:'1.29.0',title:'Kiểm chứng đồng bộ khi hai thiết bị cùng sửa',text:'Đã kiểm tra cách gộp khi hai thiết bị cùng sửa: thay đổi khác mục được gộp tự động, thay đổi cùng trường không bị ghi đè âm thầm. Thêm kiểm thử cho việc này.',tags:['Đồng bộ','Kiểm thử'],items:['Thêm kiểm thử: hai thiết bị cùng sửa, thay đổi khác mục được gộp tự động.','Thay đổi cùng một trường không bị ghi đè âm thầm.','Không đổi logic đồng bộ; danh sách xung đột theo từng mục chưa làm vì chưa có số liệu.']},{version:'1.28.0',title:'Liên kết chia sẻ bảng không còn lộ token',text:'Liên kết chia sẻ mới đưa token ra sau dấu #, nên không đi qua máy chủ và không vào nhật ký truy cập. Liên kết cũ vẫn mở được.',tags:['Chia sẻ','Bảo mật'],items:['Liên kết chia sẻ bảng đưa token ra sau dấu #, không gửi lên máy chủ.','Trang xóa token khỏi thanh địa chỉ sau khi mở.','Liên kết cũ ?boardshare= vẫn mở được.','Thu hồi và hạn 7 ngày giữ nguyên.']},{version:'1.27.0',title:'Nâng mức bảo vệ mật khẩu khi đăng nhập',text:'Mật khẩu mới được mã hóa mạnh hơn. Tài khoản cũ được nâng cấp tự động ở lần đăng nhập đúng kế tiếp. Không cần đổi mật khẩu.',tags:['Bảo mật','Đăng nhập'],items:['Mật khẩu mới băm 600.000 vòng (trước là 100.000).','Tài khoản cũ được nâng cấp tự động ở lần đăng nhập đúng kế tiếp.','Không cần thao tác và không đổi dữ liệu công việc.']},{version:'1.26.0',title:'Đăng xuất dọn bản sao dữ liệu trên thiết bị',text:'Khi đăng xuất và đã đồng bộ hết, dữ liệu tài khoản được xóa khỏi bộ nhớ trình duyệt trên thiết bị này. Nếu còn thay đổi chưa gửi, hệ thống chặn đăng xuất và giữ lại dữ liệu.',tags:['Đăng nhập','Bảo mật','Đồng bộ'],items:['Đăng xuất xóa bản sao dữ liệu tài khoản trên trình duyệt khi đã đồng bộ hết.','Nếu còn thay đổi chưa gửi, đăng xuất bị từ chối để không mất dữ liệu.','Khóa tự động cũng dọn khi không còn thay đổi chưa gửi.']},{version:'1.25.0',title:'Menu bên trái chia nhóm, mục ít dùng nằm trong Thêm',text:'Menu chia nhóm Làm việc và Ý tưởng. Lưu trữ và Thùng rác nằm trong mục Thêm thu gọn. Các mục vẫn đầy đủ, không đổi cách mở.',tags:['Điều hướng','Giao diện'],items:['Menu chia nhóm Làm việc và Ý tưởng.','Lưu trữ và Thùng rác gom vào mục Thêm thu gọn.','Các màn hình giữ nguyên, chỉ đổi cách sắp xếp menu.']},{version:'1.24.0',title:'Đăng nhập máy dùng chung và tuần mới rõ hơn',text:'Việc hằng ngày: trên điện thoại mỗi ô có số ngày và chấm hôm nay; ghi chú tiến độ cho biết còn bao nhiêu lượt. Đăng nhập có lựa chọn Máy cá nhân. Cài đặt có Đăng xuất mọi thiết bị.',tags:['Đăng nhập','Việc hằng ngày']},{version:'1.23.0',title:'Việc hằng ngày: nhận biết hôm nay và chọn biểu tượng dễ hơn',text:'Đầu bảng và chip báo đúng thứ, ngày hôm nay. Biểu mẫu căn lề đều, chọn biểu tượng có thư viện tìm kiếm như form dự án.',tags:['Việc hằng ngày','Giao diện']},{version:'1.22.1',title:'Đăng nhập nhớ tài khoản, không phải nhập lại',text:'Email đã dùng được nhớ trên thiết bị và ghi nhớ thiết bị mặc định được tích, nên không bị đăng xuất sau 10 phút.',tags:['Đăng nhập']},{version:'1.22.0',title:'Việc hằng ngày gắn dự án và mục tiêu theo tuần',text:'Mỗi việc chọn được số lần trong tuần (1–7) và dự án liên quan. Tiến độ cộng gộp theo mục tiêu; mọi ngày, kể cả T7 và CN, đều tích được.',tags:['Việc hằng ngày','Dự án']},{version:'1.21.1',title:'Giao diện trong Cài đặt dễ chọn hơn',text:'Phần Giao diện trong Cài đặt đổi sang danh sách có icon, mô tả ngắn và dấu tích ở lựa chọn đang dùng. Bấm cả dòng để chọn, vẫn dùng được bàn phím.',tags:['Giao diện']},{version:'1.21.0',title:'Báo cáo Việc hằng ngày',text:'Việc hằng ngày có thanh tiến độ cộng gộp, trạng thái hoàn thành hôm nay rõ ràng và nút Báo cáo với biểu đồ, đánh giá, đề xuất cải thiện. Biểu mẫu thêm việc gọn hơn, không tràn viền.',tags:['Báo cáo','Việc hằng ngày']},{version:'1.20.1',title:'Sửa đồng bộ Việc hằng ngày',text:'Sửa lỗi Việc hằng ngày không đồng bộ lên máy chủ (báo Chưa đồng bộ được). Dữ liệu trên thiết bị vẫn còn và sẽ tự đồng bộ.',tags:['Đồng bộ','Việc hằng ngày']},{version:'1.20.0',title:'Việc hằng ngày',text:'Thêm mục Việc hằng ngày dưới Tất cả công việc: bảng thói quen theo tuần với dấu tích có hiệu ứng nhẹ, màu riêng cho từng việc, chuỗi ngày liên tiếp, thêm, sửa và xóa.',tags:['Việc hằng ngày']},{version:'1.19.15',title:'Menu điện thoại gọn hơn',text:'Menu trên điện thoại bỏ mục Dự án và hiện khung 3 chế độ xem (Bảng Kanban, Lịch, Gantt) để chuyển ngay trong menu.',tags:['Điều hướng','Giao diện']},{version:'1.19.14',title:'Bấm × không báo chưa lưu sai',text:'Mở một việc có checklist rồi bấm × không còn hiện bảng "Bạn có thay đổi chưa lưu" khi thực tế chưa sửa gì. Sửa thật vẫn được nhắc như trước.',tags:['Thông báo','Đồng bộ']},{version:'1.19.13',title:'Nút thoát đồng bộ',text:'Mọi nút × thoát trên website nay cùng một kiểu với nút của hộp công việc: 44×44, cùng màu và bo góc. Bảng lệnh (Ctrl+K) đổi chữ "Đóng" thành nút ×.',tags:['Đồng bộ']},{version:'1.19.12',title:'Ghim công việc ngay trong hộp chi tiết',text:'Nút Ghim đặt cạnh nút Chế độ tập trung trong hàng tiêu đề của hộp công việc. Bấm để ghim hoặc bỏ ghim; việc đã ghim hiện ở menu bên trái.',tags:['Ghim','Công việc']},{version:'1.19.11',title:'Ô thêm checklist cân đối',text:'Nút "+ Thêm" và ô nhập trong ô "Thêm mục mới" của checklist nay căn giữa đều trên dưới, không còn lệch xuống dưới.',tags:['Checklist','Giao diện']},{version:'1.19.10',title:'Checklist không còn tràn viền',text:'Nút kéo ⠿ và vòng focus của dòng checklist nằm gọn trong dòng, không ló ra ngoài góc bo hay đè lên ô tick (nhất là trên điện thoại).',tags:['Checklist','Giao diện']},{version:'1.19.9',title:'Bảng thoát hiện đúng nơi đang đọc và có nút Lưu',text:'Khi thoát hộp công việc còn thay đổi chưa lưu, bảng xác nhận hiện ngay trong khung nhìn đang đọc và có nút Lưu.',tags:['Giao diện']},{version:'1.19.8',title:'Sửa tranh giành con trỏ khi vẽ lại checklist',text:'Chế độ tập trung: vẽ lại checklist sau Xóa/Hoàn tác không còn giật con trỏ khỏi ô bạn vừa chuyển tới.',tags:['Checklist','Sửa lỗi']},{version:'1.19.7',title:'Khung Chế độ xem bo tròn, thanh tiến độ checklist mỏng hơn',text:'Khung Chế độ xem ở thanh bên bo tròn; thanh tiến độ từng mục checklist mỏng hơn, đầu tô luôn bo tròn khi kéo.',tags:['Giao diện','Checklist']},{version:'1.19.6',title:'Gantt ẩn công việc đã hoàn thành',text:'Chế độ Gantt chỉ hiện việc chưa xong; việc ở cột Hoàn thành được ẩn khỏi biểu đồ.',tags:['Gantt','Công việc']},{version:'1.19.5',title:'Sửa nút Tải lại trang đè lên nút Xem chi tiết',text:'Thông báo có bản mới hiện hai nút xếp cạnh nhau, không còn chồng lên nhau.',tags:['Giao diện','Sửa lỗi']},{version:'1.19.4',title:'Checklist gọn và bo tròn hơn',text:'Mỗi dòng checklist gọn hơn, thanh tiến độ bo tròn; khung Thêm mục mới là một ô bo tròn có nút Thêm bên trong, gợi ý nằm dưới khung.',tags:['Checklist','Giao diện']},{version:'1.19.3',title:'Ghim công việc trở lại',text:'Thẻ công việc có lại nút ghim. Thanh bên có mục Ghim công việc nằm trên Ghi chú ghim nhanh: hiện tối đa 3 việc, có nút xem tất cả và bỏ ghim nhanh.',tags:['Ghim']},{version:'1.19.2',title:'Kho lời chào thêm 200 câu từ kinh điển Ấn Độ',text:'Thêm 200 trích đoạn có nguồn đối chiếu từ Upanishad, thơ Kabir và Bhagavad Gita. Kho hiện có 1.220 câu có nguồn trên mục tiêu 2.222; phần còn lại sẽ bổ sung dần theo từng bản.',tags:['Lời chào']},{version:'1.19.1',title:'Lời chào tự bật đúng 4 buổi trong ngày',text:'Lời chào Chào mừng bạn trở lại tự bật đúng lúc ở 4 buổi sáng, trưa, chiều, tối (giờ Việt Nam), mỗi buổi một câu khác nhau, kể cả khi mở tab ngầm, máy chủ chậm hoặc mạng chập chờn.',tags:['Lời chào']},{version:'1.19.0',title:'Checklist gọn hơn, có thanh tiến độ',text:'Bỏ nút lên xuống trong checklist, chỉ còn kéo thả. Mỗi mục có thanh tiến độ % tự chỉnh; tick là 100%. Tiến độ việc là trung bình các mục, tiến độ dự án là trung bình các việc.',tags:['Checklist']},{version:'1.18.4',title:'Bỏ ghim trên thẻ công việc',text:'Thẻ công việc ở bảng Kanban không còn nút ghim. Việc đã ghim trước đó vẫn hiện ở mục Pin bên trái và vẫn bỏ ghim được.',tags:['Ghim','Công việc']},{version:'1.18.3',title:'Cài đặt gọn hơn',text:'Phần Giao diện và Dung lượng dữ liệu trong Cài đặt đóng sẵn, bấm tiêu đề để mở.',tags:['Giao diện']},{version:'1.18.2',title:'Họa tiết ghi chú dịu hơn',text:'Họa tiết trên thẻ ghi chú và khung soạn giờ chỉ là nét điểm nhẹ phía sau chữ, cả chế độ sáng và tối; chữ vẫn là nội dung chính.',tags:['Ghi chú','Giao diện']},{version:'1.18.1',title:'Nút đóng hộp thoại có chuyển động',text:'Nút × ở mọi hộp thoại giờ bật vào khi mở, xoay nhẹ khi rê chuột hoặc dùng bàn phím và co lại khi nhấn; tắt khi bạn chọn giảm chuyển động.',tags:['Giao diện']},{version:'1.18.0',title:'Sửa công việc ngay trong Chế độ tập trung',text:'Sửa tên, mô tả và checklist (tích, sửa chữ, thêm, xóa có hoàn tác, đổi thứ tự) ngay trong Chế độ tập trung mà không mở hộp thoại; mọi thay đổi tự lưu.',tags:['Công việc','Chế độ tập trung']},{version:'1.17.6',title:'Thẻ việc Chế độ tập trung có hiệu ứng khi lướt chuột',text:'Thẻ việc trong Chế độ tập trung nhấc nhẹ, hiện vạch nhấn màu dự án và nhích nút Tập trung khi lướt chuột hoặc dùng bàn phím; tắt khi chọn giảm chuyển động.',tags:['Chế độ tập trung','Giao diện']},{version:'1.17.5',title:'Nút Chế độ tập trung rõ ràng hơn',text:'Nút vào Chế độ tập trung trong hộp công việc nay có chữ, nằm trong một khu vực nền nhạt bo tròn, không còn chỉ là biểu tượng khó hiểu.',tags:['Chế độ tập trung']},{version:'1.17.4',title:'Checklist dễ xem và dễ sửa',text:'Mỗi mục checklist là một thẻ bo tròn, có nút lên/xuống để đổi thứ tự bằng chạm hoặc bàn phím, ô thêm mục gọn một dòng nhấn Enter để thêm, chữ dài không còn bị cắt.',tags:['Checklist']},{version:'1.17.3',title:'Bảng Tất cả công việc dễ lọc và dễ quét',text:'Thêm chip lọc nhanh có số lượng (Tất cả, Hôm nay, Quá hạn, Sắp đến hạn, Đang thực hiện) và làm bảng công việc dễ quét hơn: trạng thái thẳng hàng có chấm màu, hàng quá hạn tô nhẹ.',tags:['Công việc']},{version:'1.17.2',title:'Ghi chú ghim nhanh dễ nhìn hơn',text:'Khu Ghi chú ghim nhanh ở thanh bên có ô màu theo màu ghi chú, tên, dòng xem trước, nút bỏ ghim dạng biểu tượng và lối tắt Tất cả ghi chú.',tags:['Ghi chú','Ghim']},{version:'1.17.1',title:'Thông báo gọn và dễ quét hơn',text:'Hộp thoại Thông báo gom việc theo nhóm Quá hạn, Sắp đến hạn, Quan trọng với số lượng, mỗi việc một hàng gọn; thanh nhắc hạn và hộp Công việc cần chú ý có màu theo mức độ.',tags:['Thông báo']},{version:'1.17.0',title:'Nút chế độ sáng/tối cạnh chuông',text:'Thêm nút chuyển nhanh giao diện sáng/tối ngay cạnh biểu tượng thông báo trên thanh trên cùng, dùng được trên điện thoại, máy tính bảng và máy tính.',tags:['Chế độ tối','Giao diện']},{version:'1.16.6',title:'Gỡ chế độ xem Dòng thời gian',text:'Bỏ hoàn toàn chế độ xem Dòng thời gian khỏi menu, thanh chế độ xem trên điện thoại và hướng dẫn. Còn Bảng Kanban, Lịch và Gantt; dữ liệu ngày của công việc giữ nguyên.',tags:['Điều hướng']},{version:'1.16.5',title:'Lời chào hiện đủ 4 buổi trong ngày',text:'Sửa lỗi lời chào Chào mừng bạn trở lại không hiện lại ở các buổi sáng, trưa, chiều, tối sau khi đã bấm đã đọc một lần.',tags:['Lời chào']},{version:'1.16.4',title:'Xóa Thùng rác không cần mật khẩu',text:'Dọn sạch Thùng rác, xóa vĩnh viễn từng mục và xóa tệp đính kèm trong Thùng rác không còn đòi nhập lại mật khẩu, nên bấm Đồng bộ cũng không bị hỏi nữa; vẫn có hộp xác nhận và cảnh báo không thể hoàn tác. Chia sẻ vẫn cần mật khẩu.',tags:['Thùng rác']},{version:'1.16.3',title:'Xóa dự án đúng dự án',text:'Nút Xóa dự án này trong biểu mẫu dự án nay xóa đúng dự án đang được sửa, không còn dựa vào dự án đang mở phía sau. Cách mở biểu mẫu, hộp xác nhận và việc chuyển vào Thùng rác không đổi.',tags:['Dự án','Sửa lỗi']},{version:'1.16.2',title:'Chế độ tối hoàn thiện hơn',text:'Biểu đồ Gantt và vòng Bức tranh công việc đã có nền tối, nhãn ngày sáng rõ. Nút Làm mới ở Chế độ tập trung không còn bị trắng khi bật tương phản cao. Chỉ đổi giao diện tối và tương phản cao; dữ liệu và chế độ sáng không đổi.',tags:['Chế độ tối']},{version:'1.16.1',title:'Khởi động ổn định hơn',text:'Ứng dụng báo rõ khi đã khởi động xong, để màn hình đăng nhập và các thao tác ngay sau khi mở không bị xóa nhầm bởi bước tải dữ liệu còn đang chạy. Dữ liệu và giao diện không đổi.',tags:['Sửa lỗi']},{version:'1.16.0',title:'Chế độ tối và tương phản cao',text:'Giao diện có thêm chế độ tối và tương phản cao. Mặc định theo cài đặt của thiết bị; có thể chọn tay trong Cài đặt → Giao diện hoặc bằng Ctrl+K. Lựa chọn chỉ lưu trên thiết bị này, không ảnh hưởng dữ liệu.',tags:['Chế độ tối','Giao diện']},{version:'1.15.54',title:'Dọn mã giao diện (đợt 1)',text:'Gỡ 51 khai báo giao diện thừa đã bị ghi đè hoàn toàn và đặt ngân sách để số quy tắc ép buộc không tăng lại. Giao diện không đổi; đây là bước chuẩn bị cho chế độ tối.',tags:['Mã nguồn']},{version:'1.15.53',title:'Nút xóa việc và dự án tinh tế hơn',text:'Khu vực xóa việc và xóa dự án có biểu tượng thùng rác, tiêu đề và lời giải thích rõ (chuyển vào Thùng rác, khôi phục được trong 30 ngày), nút viền đỏ nhạt thay vì khối đỏ đặc. Cách xóa và xác nhận không đổi.',tags:['Công việc','Giao diện']},{version:'1.15.52',title:'Việc hoàn thành chìm xuống',text:'Thẻ việc ở cột Hoàn thành được rút màu, nền xám nhạt, tiêu đề gạch ngang và nhãn chuyển xám để mắt không phải chú ý tới nữa. Chữ vẫn rõ, đưa chuột hoặc chọn thẻ thì thẻ hiện lại đầy đủ.',tags:['Công việc','Giao diện']},{version:'1.15.51',title:'Ghim ghi chú rõ ràng hơn',text:'Khu vực ghim trong ghi chú có biểu tượng minh họa, tiêu đề và mô tả cho từng kiểu ghim (lên đầu danh sách, ghim nhanh ở menu). Ghim đang bật đổi màu nổi bật, nút to dễ bấm trên điện thoại. Cách ghim và bỏ ghim không đổi.',tags:['Ghim','Ghi chú']},{version:'1.15.50',title:'Bỏ họa tiết ở dự án và việc',text:'Dự án và việc không còn lựa chọn họa tiết, thẻ và trang không còn vẽ họa tiết nền nên dễ đọc hơn. Họa tiết bạn đã chọn trước đây vẫn được giữ trong dữ liệu, không bị xóa hay ghi đè khi lưu. Ghi chú vẫn có họa tiết như cũ.',tags:['Dự án','Giao diện']},{version:'1.15.49',title:'Lịch dạng danh sách cho màn hình vừa',text:'Ở máy tính bảng, trang Lịch hiện theo danh sách từng ngày dễ đọc thay cho lưới 7 cột chật; có nút đổi qua lại giữa Danh sách và Lưới tháng, và máy nhớ lựa chọn của bạn.',tags:['Lịch']},{version:'1.15.48',title:'Gantt dễ kéo bằng ngón tay',text:'Trên màn hình cảm ứng, đầu kéo và nút nối của biểu đồ Gantt có vùng chạm 44px nên kéo dời lịch hoặc nối phụ thuộc bằng ngón tay không còn trượt; trên chuột mọi thứ giữ nguyên.',tags:['Gantt']},{version:'1.15.47',title:'Hộp thoại còn lại dễ chạm hơn',text:'Sáu hộp thoại trước đây chưa được kiểm tra truy cập (báo cáo tuần, chia sẻ báo cáo, chọn ngày, lời chào, tải tệp, thanh lệnh) nay đã được quét; nút Tháng trước/Tháng sau của bảng chọn ngày và nút Đóng lời chào được nới lên 44px trên màn hình cảm ứng. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.46',title:'Một nơi báo sự cố đồng bộ',text:'Khi đồng bộ gặp sự cố (máy chủ từ chối, dữ liệu không hợp lệ, xung đột), thông báo nổi không còn nói lại điều viên thuốc và khung báo lỗi đã nói; khung có thêm một dòng trấn an rằng bản nháp vẫn ở thiết bị. Dòng tự lưu của ghi chú và vài thông báo còn lại dùng chung chữ trên thiết bị. Không đổi dữ liệu và cách đồng bộ.',tags:['Đồng bộ','Thông báo']},{version:'1.15.45',title:'Thẻ gọn và checklist khớp nhau',text:'Khi Thẻ gọn đang ẩn checklist trên thẻ, ô Hiện checklist trên thẻ trong menu Hiển thị nay bỏ dấu, bị khóa và ghi rõ lý do thay vì vẫn đánh dấu như đang hiện. Lựa chọn bạn đã lưu không bị đổi và trở lại khi tắt Thẻ gọn. Không đổi dữ liệu.',tags:['Checklist','Công việc']},{version:'1.15.44',title:'Một trạng thái lưu',text:'Trạng thái lưu và đồng bộ nay dùng một bộ chữ và một cách phân loại ở mọi nơi: viên thuốc ở thanh trên, khung báo lỗi bên dưới và dòng trạng thái trong hộp thoại chi tiết việc cùng nói một điều. Nhãn lỗi không còn lặp chữ Chưa đồng bộ; khi máy chủ lỗi mà vẫn có mạng thì ghi Chưa kết nối được thay vì Ngoại tuyến; viên thuốc dùng nhãn ngắn, khung lỗi nêu đầy đủ kèm nút Thử lại, không lặp một câu hai lần. Bỏ nhãn Báo cáo đồng bộ không bấm được ở chân thanh bên (báo cáo vẫn nằm trong Cài đặt). Không đổi dữ liệu và cách đồng bộ.',tags:['Đồng bộ']},{version:'1.15.43',title:'Một kênh nhắc việc',text:'Việc quá hạn và việc đến hạn trong 3 ngày nay nhắc chủ yếu ở một nơi là thanh nhắc đầu trang; số trên chuông bằng đúng số ở thanh đó (trước đây thanh nhắc, chuông và thông báo nổi mỗi nơi một số, và thông báo nổi lặp lại cùng tin mỗi giờ). Thông báo nổi chỉ hiện khi có việc mới đến hạn, không lặp lại. Phiên bản mới, tệp mới và nhắc ghi chú báo bằng một chấm nhỏ cạnh chuông, không cộng vào số. Hộp thoại Thông báo mở đầu bằng một dòng tóm tắt khớp với số trên chuông. Không đổi dữ liệu.',tags:['Thông báo']},{version:'1.15.42',title:'Danh sách việc gọn hơn',text:'Màn hình Tất cả công việc gọn hơn: mỗi việc một hàng thấp (khoảng 53px trên máy tính, 123px trên điện thoại thay vì 309px), tên dự án nằm ngay dưới tên việc, ngày và ưu tiên là chip bấm để sửa. Không còn nhãn Hạn chót lặp ở từng hàng; việc quá hạn ghi một lần, việc đã xong nằm cuối danh sách. Có dòng giải thích ô vuông dùng để chọn nhiều việc. Không đổi dữ liệu.',tags:['Công việc']},{version:'1.15.41',title:'Dễ chạm, dễ dùng bàn phím',text:'Hộp thoại thêm việc, dự án mới và ghi chú mới mở vào thẳng ô tên (trên điện thoại, việc đã có thì không bật bàn phím); mọi hộp thoại có tên để trình đọc màn hình đọc. Trên màn hình cảm ứng, nút, ô chọn và ô nhập chính cao tối thiểu 44px; ở mọi thiết bị mỗi điều khiển tối thiểu 24px. Chi tiết việc trên điện thoại: phím Tab đi đúng thứ tự nhìn. Sửa tiêu đề trùng chữ ở hộp thoại Cài đặt. Không đổi dữ liệu.',tags:['Điều hướng','Giao diện']},{version:'1.15.40',title:'Chữ dễ đọc hơn',text:'Chữ nhỏ nhất nay là 12px (trước có chỗ chỉ 8–11px); chữ phụ, nhãn, hạn và tab dùng màu đậm hơn để đạt tương phản tối thiểu 4,5:1; nút tím–hồng sẫm hơn để chữ trắng đọc rõ; viền ô nhập và chữ gợi ý rõ hơn. Thẻ Hoàn thành và tab dự án không chọn không còn bị làm mờ cả chữ. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.39',title:'Từ ngữ giao diện thống nhất',text:'Giao diện dùng một bộ từ tiếng Việt: Bảng Kanban, Dòng thời gian, Lịch, Cài đặt, việc (thay cho task), Hoàn thành (thay cho Done) và Giới hạn việc mỗi cột (thay cho WIP). Ô Cột trong biểu mẫu việc hiện tên cột đang dùng thay vì Idea, List, Doing, Done. Thanh chế độ xem trên điện thoại hiện đủ tên mới nên cao hơn vài điểm ảnh. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.38',title:'Thẻ gọn mặc định trên điện thoại',text:'Trên điện thoại, thẻ công việc mặc định ở chế độ gọn (ẩn mô tả, checklist và bước tiếp theo) để cột ngắn lại và ít phải cuộn; có thể chọn Thẻ gọn tắt trong menu Hiển thị và lựa chọn đó được giữ. Màn hình rộng vẫn mặc định thẻ đầy đủ. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.37',title:'Gom nút phụ vào menu Hiển thị',text:'Thẻ gọn, Giới hạn WIP và Lệnh nhanh nằm trong menu Hiển thị của dự án thay vì một hàng nút riêng dưới khối tiến độ, nên thẻ đầu tiên lên cao hơn. Các nút vẫn làm việc như cũ; Ctrl/⌘ K vẫn mở Lệnh nhanh. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.36',title:'Đầu trang dự án gọn hơn',text:'Đầu trang dự án chỉ còn một nút chính là Thêm việc; Ghim, Lưu trữ, Tệp và Sửa dự án nằm trong menu Tùy chọn. Khối tiến độ ghi rõ số việc đã xong (ví dụ 3/14 việc xong) cùng phần trăm. Trên điện thoại thẻ đầu tiên hiện ngay trong màn hình đầu. Không đổi dữ liệu.',tags:['Dự án','Giao diện']},{version:'1.15.35',title:'Thẻ Kanban gọn hơn',text:'Nút chuyển nhanh thu thành mũi tên cạnh hạn thay vì một hàng riêng ở mỗi thẻ; việc chưa có checklist không còn hiện 0% và thanh tiến độ trống; khoảng cách trong thẻ chặt hơn. Thẻ thấp hơn khoảng 43%. Không đổi dữ liệu.',tags:['Công việc','Giao diện']},{version:'1.15.34',title:'Khung điều hướng ổn định',text:'Từ màn hình 701px, thanh trên (ô tìm kiếm, trạng thái đồng bộ) và dải tab dự án luôn nằm ở đầu màn hình khi cuộn; chuyển màn hình thì về đầu trang. Đường dẫn của trang Lưu trữ và Thùng rác không còn trống. Không đổi dữ liệu.',tags:['Điều hướng']},{version:'1.15.33',title:'Sửa bố cục tablet',text:'Tên dự án và tiêu đề trang không còn bị bóp thành từng chữ ở màn hình 701–1000px; phần trăm tiến độ trên tab không còn bị bẻ dòng; thanh trên không còn tràn ngang. Không đổi dữ liệu.',tags:['Giao diện']},{version:'1.15.32',title:'Lịch gọn hơn cho task dài ngày',text:'Task nhiều ngày hiện thành một thanh liền xuyên các ngày trong tuần thay vì lặp một thẻ ở mỗi ngày. Không đổi dữ liệu.',tags:['Lịch']},{version:'1.15.31',title:'Sửa giao diện thẻ công việc',text:'Nút chuyển nhanh nằm gọn trong thẻ, không còn tràn ra ngoài; họa tiết phủ nhẹ lên nền thẻ thay cho ô vuông lệch. Không đổi dữ liệu.',tags:['Công việc','Giao diện']},{version:'1.15.30',title:'Tài liệu khớp thực tế',text:'Cập nhật tài liệu dự án cho đúng cách phát hành và triển khai. Không đổi tính năng, dữ liệu hay giao diện.',tags:['Tài liệu']},{version:'1.15.29',title:'Ghim nhanh ghi chú và task',text:'Tách Ghim ghi chú và Ghim nhanh; tối đa 3 ghi chú ghim nhanh trên thanh tab, mục Pin trong menu dành cho task. Họa tiết ghi chú phủ nhẹ từng thẻ và khung soạn.',tags:['Ghim','Ghi chú']},{version:'1.15.25',title:'Ghim nhanh ghi chú và task',text:'Thêm truy cập nhanh ghi chú và ghim task trong menu.',tags:['Ghim']},{version:'1.15.24',title:'Mobile calendar, checklist và dự án',text:'Cải thiện lịch mobile, checklist, họa tiết dự án và xác nhận khôi phục.',tags:['Lịch','Checklist']},{version:'1.14.7',title:'Gantt linh hoạt, báo cáo rõ ràng',text:'Tạo công việc trực tiếp từ ngày trên Gantt và sắp xếp nhanh các việc chưa có lịch. Căn chỉnh nút Focus gọn hơn; cải thiện cách trình bày phân bố trạng thái, tổng kết dự án và nhịp tuần trong báo cáo PDF.',tags:['Gantt','Báo cáo']},{version:'1.14.6',title:'Báo cáo rõ ràng, lịch gọn nhẹ',text:'Tối ưu bố cục in và lưu PDF; chia sẻ báo cáo mặc định công khai trong 1 ngày. Gõ 1. hoặc * rồi Space để tạo danh sách và tiếp tục bằng Enter. Lịch task dùng ngày bắt đầu/kết thúc, trong đó ngày kết thúc là hạn; nút Focus có chú thích và căn chỉnh gọn hơn.',tags:['Báo cáo','Lịch']},{version:'1.14.4',title:'Dự án rõ nhịp, tập trung dễ hơn',text:'Ngày và họa tiết dự án, Timeline gọn trong thẻ, truy cập tập trung nhanh, kiểm tra dữ liệu tự động và thủ công. Cải thiện nút Lưu, menu danh sách, liên kết ghi chú, bộ lọc và chi tiết báo cáo web.',tags:['Dự án']},{version:'1.14.3',title:'Lời chào nhẹ nhàng, thông báo đồng bộ',text:'Làm gọn lời chào; xác nhận đã đọc theo tài khoản trên mọi thiết bị. Thêm 30 lời khích lệ khi hoàn thành việc, sửa khung mô tả và Timeline, bổ sung họa tiết Nông trại, Gia đình, Tài chính cho ghi chú và công việc.',tags:['Thông báo','Đồng bộ']},{version:'1.14.2',title:'Khôi phục mốc đồng bộ',text:'Khôi phục phiên bản đồng bộ bị thiếu bằng hợp nhất an toàn. Phân biệt lỗi mốc phiên bản với nội dung, hiển thị phản hồi cụ thể từ máy chủ.',tags:['Đồng bộ']},{version:'1.13.2',title:'Giữ an toàn bản nháp',text:'Giữ bản nháp chưa đồng bộ khi mở lại tài khoản; báo rõ dung lượng hoặc dữ liệu chưa hợp lệ. Lịch sử ghi chú có thể xem khi bản nháp đang chờ; tinh gọn bộ lọc và giao diện tập trung.',tags:['Ghi chú']},{version:'1.13.1',title:'Gọn lựa chọn, rõ trạng thái',text:'Bộ lọc dạng nhãn màu bo tròn, Cài đặt chia nhóm, nút thêm checklist canh phải. Dọn Thùng rác chờ đồng bộ đang chạy và trả kết quả rõ ràng.',tags:['Giao diện']},{version:'1.13.0',title:'Một việc mỗi lúc',text:'Chế độ tập trung gom việc đến hạn, quá hạn và gợi ý ba ưu tiên. Ghi chú liên kết xuất hiện trong dự án, mô tả dự án có định dạng và lựa chọn liên kết được thu gọn.',tags:['Công việc']},{version:'1.12.1',title:'Gọn bộ lọc, rõ công việc',text:'Bộ lọc thu gọn, bình luận rộng hơn, liên kết từ ghi chú sang công việc/dự án. Ghi nhớ dự án gần nhất và nhấn mạnh tab đang xem; kết quả tìm kiếm có từ khóa nổi bật.',tags:['Công việc']},{version:'1.12.0',title:'Làm việc liền mạch hơn',text:'Giữ vị trí checklist khi sắp xếp; thêm mẫu công việc, bình luận, nhãn trạng thái và liên kết ghi chú. Đồng bộ rõ ràng trên mobile, lịch sử ghi chú dạng dòng thời gian và thao tác nhiều task.',tags:['Điều hướng']},{version:'1.11.2',title:'Củng cố logic, gọn mã nguồn',text:'Gom logic hiển thị trùng, dọn listener khi đóng form, thống nhất luồng tự lưu ghi chú. Kéo thả bỏ qua vị trí không hợp lệ và thao tác không thay đổi; kiểm tra tên cột ở trình duyệt và máy chủ.',tags:['Mã nguồn']},{version:'1.11.1',title:'Tinh chỉnh không gian làm việc',text:'Số ghi chú theo từ khóa, lịch sử 7 ngày gọn hơn, nút đồng bộ mobile, thông báo đã xem và đổi tên cột Kanban.',tags:['Giao diện']},{version:'1.11.0',title:'Giữ nhịp làm việc quen thuộc',text:'Chuyển và copy task giữa dự án, lưu trữ task, định dạng mô tả, thêm và sắp xếp checklist nhanh. Ghi chú tự lưu đầy đủ và kéo thả bằng tay nắm.',tags:['Giao diện']},{version:'1.10.2',title:'Ảnh ghi chú gọn gàng',text:'Sửa ảnh đính kèm còn sót sau khi gỡ để thẻ ghi chú giữ bố cục ổn định; tự ẩn ảnh tải lỗi.',tags:['Ghi chú']},{version:'1.10.1',title:'Tệp đính kèm gọn gàng',text:'Nhóm ảnh riêng khỏi tài liệu và các loại tệp khác; thu nhỏ ảnh xem trước theo khung, tên tệp dễ đọc và gỡ tệp ngay tại chỗ. Ảnh xem trước liên kết có hình dự phòng khi tệp ảnh không tải được. Đồng bộ số phiên bản 1.10.1 trên toàn ứng dụng.',tags:['Tệp đính kèm']},{version:'1.9.11',title:'Đồng bộ an tâm',text:'Sửa trạng thái đồng bộ kéo dài và cảnh báo sai, phân biệt lưu cục bộ/chờ mạng/dữ liệu bị từ chối; có giới hạn thời gian chờ và nút thử lại, không tự ghi đè bản khác.',tags:['Đồng bộ']},{version:'1.9.10',title:'Họa tiết an nhiên',text:'Nút ghim/bỏ ghim có hàng riêng, không đè lên tiêu đề ghi chú. Nâng cấp tám tranh nền thiên nhiên và thiền, thêm ảnh mẫu thu nhỏ để chọn trực quan, tương phản chữ rõ trên desktop/mobile.',tags:['Giao diện']},{version:'1.9.9',title:'Soạn thảo trực tiếp',text:'Định dạng ngay trong vùng nhập ghi chú; cải thiện tìm kiếm theo nhóm và sửa trạng thái, cơ chế đồng bộ dữ liệu tự động.',tags:['Ghi chú']},{version:'1.9.8',title:'Ghi chú sinh động',text:'Ghim ghi chú như Keep, tìm tệp và nội dung toàn dự án, họa tiết minh họa toàn thẻ, thanh định dạng văn bản, thumbnail và sửa nút đóng.',tags:['Ghi chú']},{version:'1.9.7',title:'Checklist nở hoa',text:'Checklist ghi chú có nút Thêm mục lưu tự động, thanh tiến độ trực quan và tám họa tiết thiên nhiên, thiền, yoga, tỉnh thức trên từng thẻ.',tags:['Checklist']},{version:'1.9.6',title:'Tìm kiếm ghi chú mở rộng',text:'Mở kết quả ghi chú từ thanh tìm kiếm chung và tối ưu giao diện nhập liệu trên điện thoại.',tags:['Tìm kiếm','Ghi chú']},{version:'1.9.5',title:'Ghi chú & Tài nguyên',text:'Gom ba tùy chọn ghi chú trên desktop, thu gọn thanh tab dự án và tải tệp ngay trong Tài nguyên.',tags:['Ghi chú','Tài nguyên']},{version:'1.9.4',title:'Giao diện linh hoạt',text:'Cải thiện hộp thoại, nút đóng và tab dự án trên nhiều kích thước màn hình.',tags:['Giao diện']},{version:'1.9.3',title:'Ghi chú gọn, sáng rõ',text:'Tối ưu nhập ghi chú trên Mobile: khung soạn vừa màn hình, giảm chiều cao các trường, nhóm tùy chọn phụ, sửa vị trí hiển thị và dễ lưu khi chạm.',tags:['Ghi chú']},{version:'1.9.2',title:'Học sâu, trở về mình',text:'Bổ sung 261 trích đoạn có nguồn: Mạnh Tử, Nam Hoa Kinh, Tuân Tử và các nguồn chính thức. Lưu nguyên bản, vị trí chương và bản tiếng Việt; phân biệt lời nhân vật trong tác phẩm với phát ngôn lịch sử.',tags:['Lời chào']},{version:'1.9.1',title:'Lời có nguồn, ngày có nhịp',text:'Bổ sung 185 trích đoạn có nguồn và bản tiếng Việt; toàn bộ trích đoạn tham gia vòng chọn, không lặp trong một chu kỳ. Lời biên soạn được giữ riêng và không tính vào mục tiêu 3.333.',tags:['Lời chào']},{version:'1.9.0',title:'Bốn mùa trong ngày',text:'Lời chào theo bốn buổi giờ Việt Nam, hồ sơ tư tưởng, nguồn tham khảo và chân dung tư liệu của các vị thầy.',tags:['Lời chào']},{version:'1.8.4',title:'Task cuộn liền mạch',text:'Thanh đầu của cửa sổ task cuộn cùng nội dung, giúp tập trung đọc và chỉnh sửa.',tags:['Công việc']},{version:'1.8.3',title:'Chữ rõ, việc nhẹ',text:'Tinh chỉnh font nhãn dự án và nội dung task để dễ đọc trên desktop, tablet và điện thoại.',tags:['Giao diện']},{version:'1.8.2',title:'Nhịp việc rõ ràng',text:'Thông báo đến hạn cuộn theo trang; báo cáo có khoảng lề rõ ràng; nhãn dự án theo màu; lưu task và đóng form, bấm thanh Gantt để sửa trực tiếp.',tags:['Công việc']},{version:'1.8.1',title:'Thanh âm ngày mới',text:'Nhạc nền Bamboo at Daybreak có nút phát, tạm dừng, âm lượng và màu tương phản theo nền. Phiên bản tự cập nhật trên màn hình đăng nhập.',tags:['Thông báo']},{version:'1.8.0',title:'Chia sẻ điều đang lớn',text:'Chia sẻ báo cáo qua web công khai hoặc có mật khẩu, chọn hạn 1–30 ngày và thu hồi. Mở rộng thư viện icon theo nhóm, tìm tiếng Anh; ghi chú có bánh xe màu HEX/RGB.',tags:['Chia sẻ']},{version:'1.7.0',title:'Dòng việc liền mạch',text:'Kéo đổi lịch Gantt trực tiếp, checklist ngay trên thẻ, ghi chú có từ khóa và email nhắc hạn, Thùng rác theo lưới/danh sách cùng thống kê và xóa có xác nhận.',tags:['Điều hướng']},{version:'1.6.3',title:'Chạm để hiểu',text:'Các ô thống kê mở danh sách và tiến độ chi tiết, hiệu ứng chuyển động nhẹ, thanh nhắc hạn dễ thao tác và ảnh hồ sơ hiển thị tại avatar.',tags:['Điều hướng']},{version:'1.6.2',title:'Nhịp an nhiên',text:'Form ghi chú và công việc rõ ràng, Mức độ bốn màu, font mềm mại, biểu đồ tròn trong PDF và phiên làm việc tự khóa sau 10 phút không thao tác.',tags:['Lời chào']},{version:'1.6.1',title:'Thông báo mở đúng chi tiết',text:'Nút Xem chi tiết mở phiên bản hoặc công việc liên quan, đồng bộ icon Dashboard mềm mại và thu gọn phiên bản cuối trang.',tags:['Thông báo']},{version:'1.6.0',title:'Gantt, ghi chú và tài nguyên',text:'Gantt có liên kết phụ thuộc và chặn vòng lặp; mở trực tiếp ghi chú, khung soạn bo tròn, tìm icon tiếng Anh và đổi tên tài nguyên.',tags:['Gantt','Ghi chú','Tài nguyên']},{version:'1.5.0',title:'Điều hướng & không gian làm việc tinh tế',text:'Kéo sắp xếp tab, tiến độ dự án đa chế độ, từ khóa dự án, lịch chọn ngày giờ, xác nhận lưu trữ và danh sách việc cần chú ý.',tags:['Điều hướng']},{version:'1.4.1',title:'Checklist gọn & thư viện tài nguyên',text:'Checklist một dòng, tổng kết email có biểu đồ % và tiến độ từng dự án, xem trước/In/Lưu PDF, album Tài nguyên riêng tư quản lý tệp.',tags:['Checklist','Tài nguyên']},{version:'1.4.0',title:'Bức tranh công việc & tổng kết tuần',text:'Biểu đồ tương tác bốn màu, nhắc hạn trước 3 ngày, email tổng kết Chủ nhật trong Settings, bảng icon và bánh xe HEX/RGB. Lưu trữ dự án đang làm dở.',tags:['Báo cáo']},{version:'1.3.8',title:'Lời chào mỗi ngày tinh gọn hơn',text:'Lược bỏ phần hiển thị bản dịch và bản tiếng Anh, cải thiện kiểu chữ, căn dòng và nút đóng.',tags:['Lời chào']},{version:'1.3.7',title:'Ma trận ưu tiên bốn màu',text:'Cập nhật bốn nhãn theo mức độ quan trọng và khẩn cấp: tím, xanh lá, hồng và cam.',tags:['Công việc']},{version:'1.3.6',title:'Toàn cảnh & công việc trong một màn hình',text:'Thống kê quá hạn, tổng quan đầu trang mobile, chỉnh task trực tiếp, ma trận bốn màu, tùy chọn Kanban và tiến độ Timeline/Calendar. Hướng dẫn đầy đủ.',tags:['Giao diện','Công việc']},{version:'1.3.4',title:'Thông báo đã xem & chuyển bước công việc',text:'Nút Đã xem tất cả đưa bộ đếm về bình thường. Chuyển task sang cột kế tiếp ngay trên thẻ.',tags:['Thông báo','Công việc']},{version:'1.3.3',title:'Ghi chú trực tiếp & lời chào mỗi ngày',text:'Viết ghi chú, thêm liên kết và tải tệp trong cùng khung. Lời chào hằng ngày có họa tiết thiên nhiên.',tags:['Ghi chú','Lời chào']}];
let latestVersion=APP_VERSION;
function localRead(k){try{return localStorage.getItem(k);}catch{return null;}}
function localWrite(k,v){try{localStorage.setItem(k,v);}catch{}}
// Read receipts belong to the signed-in account, independently of workspace revisions.
let readReceiptOwner=null,readReceiptKeys=new Set(),readReceiptLoaded=false,readReceiptRequest=null,readReceiptTime=0;
function noticeReceipt(t){return 'notice:'+encodeURIComponent(noticeSignature(t));}
async function loadReadReceipts(force=false){
 const owner=currentUser?.id;if(!owner)return false;
 if(readReceiptOwner!==owner){readReceiptOwner=owner;readReceiptKeys=new Set();readReceiptLoaded=false;readReceiptRequest=null;readReceiptTime=0;}
 if(readReceiptRequest)return readReceiptRequest;
 if(readReceiptLoaded&&!force&&Date.now()-readReceiptTime<10000)return true;
 const pending=(async()=>{try{const result=await requestAPI('notification-receipts');if(currentUser?.id!==owner||readReceiptOwner!==owner)return false;if(!Array.isArray(result.keys))throw Error('Invalid receipts');readReceiptKeys=new Set(result.keys.filter(k=>typeof k==='string'));readReceiptLoaded=true;readReceiptTime=Date.now();refreshBell();if(readReceiptKeys.has(welcomeReceipt(welcomeSlot())))document.querySelector('.welcome-dialog:not([data-manual])')?.close();return true;}catch{return false;}})();
 readReceiptRequest=pending;try{return await pending;}finally{if(readReceiptRequest===pending)readReceiptRequest=null;}
}
async function saveReadReceipts(keys){
 const owner=currentUser?.id;if(!owner)throw Error('Vui lòng đăng nhập.');
 for(let i=0;i<keys.length;i+=200)await requestAPI('notification-receipts','PUT',{keys:keys.slice(i,i+200)});
 if(currentUser?.id!==owner)throw Error('Tài khoản đã thay đổi.');
 if(readReceiptOwner!==owner){readReceiptOwner=owner;readReceiptKeys=new Set();readReceiptLoaded=false;}
 keys.forEach(key=>readReceiptKeys.add(key));refreshBell();
}
function releaseKey(){return 'zen-release-seen:'+currentUser?.id;}
function releaseUnread(){return !!currentUser&&!(readReceiptOwner===currentUser.id&&readReceiptKeys.has('release:'+latestVersion))&&localRead(releaseKey())!==latestVersion;}
const oldBellRefresh=refreshBell;refreshBell=function(){oldBellRefresh();if(releaseUnread()){const count=taskNotices().length+fileAlerts.length+1;bell.innerHTML=svgIcon('bell')+'<span class="notification-count">'+(count>99?'99+':count)+'</span>';bell.setAttribute('aria-label','Thông báo · '+count+' mục, có phiên bản mới');}};
const oldBellClick=bell.onclick;bell.onclick=()=>{oldBellClick();const list=$('#editor-body .notice-list');if(!releaseUnread())return;list.insertAdjacentHTML('afterbegin',`<article class="notice-item release-notice"><strong>${releaseUnread()?'Mới · ':''}Phiên bản ${esc(latestVersion)}</strong><span>${latestVersion===APP_VERSION?esc(RELEASES[0].text):'Có bản cập nhật mới. Tải lại trang để nhận tính năng mới nhất.'}</span><div class="release-actions"><button class="btn" type="button" id="release-read">${svgIcon('notes')}Xem chi tiết</button>${latestVersion!==APP_VERSION?'<button class="btn" id="release-reload" type="button">Tải lại trang</button>':''}</div></article>`);$('#release-read').onclick=async e=>{e.currentTarget.disabled=true;try{await saveReadReceipts(['release:'+latestVersion]);localWrite(releaseKey(),latestVersion);refreshBell();$('#editor').close();go('versions');}catch{notify('Chưa lưu được trạng thái đã đọc. Hãy thử lại.');e.target.closest('button').disabled=false;}};if($('#release-reload'))$('#release-reload').onclick=()=>location.reload();};
const releaseBullets=r=>Array.isArray(r.items)&&r.items.length?r.items:String(r.text||'').split(/(?<=[.!?])\s+/).filter(Boolean);
versions=()=>heading('NHẬT KÝ PHÁT TRIỂN','Phiên bản '+APP_VERSION,'Mỗi phiên bản một khung, kèm từ khóa hạng mục đã cải thiện')+'<section class="release-log" aria-label="Nhật ký phiên bản">'+RELEASES.map(r=>`<article class="release-card"><header><span class="release-ver">v${esc(r.version)}${r.name?' · '+esc(r.name):''}</span><h4>${esc(r.title)}</h4></header>${(r.tags||[]).length?`<div class="release-tags" aria-label="Từ khóa">${r.tags.map(t=>`<span class="release-tag">${esc(t)}</span>`).join('')}</div>`:''}<ul>${releaseBullets(r).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article>`).join('')+'</section>';
async function checkRelease(){if(!currentUser||document.hidden||!navigator.onLine)return;try{const r=await fetch('/health',{cache:'no-store'});if(r.ok){const body=await r.json();if(/^\d+\.\d+\.\d+$/.test(body.version)){latestVersion=body.version;refreshBell();}}}catch{}}
let wisdomCache=null,teacherCache=null,welcomeLoading=false,welcomeSession=new Set();
function welcomeDay(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function wisdomIndex(day,count){return Math.floor((Date.parse(day+'T00:00:00Z')-Date.parse('2026-10-24T00:00:00Z'))/86400000+count*1000)%count;}
// v1.16.5: dấu "đã đọc" của lời chào riêng cho từng buổi (ngày + buổi 0-3); trước đây chỉ một dấu 'welcome' vĩnh viễn nên bấm đọc một lần là các buổi sau không bao giờ hiện lại.
function welcomeReceipt(time){return 'welcome:'+time.day+':'+time.slot;}
function welcomeSlot(now=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(now),v=Object.fromEntries(parts.map(p=>[p.type,p.value])),hour=Number(v.hour),slot=hour<5?3:hour<11?0:hour<14?1:hour<18?2:3,calendarDay=v.year+'-'+v.month+'-'+v.day,day=hour<5?new Date(Date.parse(calendarDay+'T00:00:00Z')-86400000).toISOString().slice(0,10):calendarDay;return {day,slot,label:['Buổi sáng','Buổi trưa','Buổi chiều','Buổi tối'][slot],serial:Math.floor(Date.parse(day+'T00:00:00Z')/86400000)*4+slot};}
// Pure selection functions are embedded into welcome.js at build-authoring time.
// Every excerpt occurs exactly once in a complete cycle, including authors
// without a profile. Entries for each author are spread across the cycle.
function welcomeAllowed(entry) {
  return !/marcus\s+aurelius|stoic|khắc\s*kỷ|khac\s*ky|epictetus|seneca/i.test([entry.author,entry.name,entry.id,entry.school,entry.theme,entry.source].filter(Boolean).join(' '));
}
function welcomeProfile(author, profiles) {
  return profiles.filter(p => welcomeAllowed(p) && (author === p.name || author.startsWith(p.name + ' ·')))
    .sort((a,b) => b.name.length - a.name.length)[0];
}
function welcomeHash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function welcomeDeck(quotes, profiles) {
  const groups = new Map();
  for (const quote of quotes) {
    if (!welcomeAllowed(quote) || typeof quote.vi !== 'string' || !quote.vi.trim()) continue;
    const profile = welcomeProfile(quote.author, profiles);
    const key = profile?.id || quote.author;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({quote,profile});
  }
  const deck = [];
  for (const [key, entries] of groups) {
    entries.sort((a,b) => welcomeHash(a.quote.id || a.quote.vi) - welcomeHash(b.quote.id || b.quote.vi)
      || a.quote.vi.localeCompare(b.quote.vi));
    entries.forEach((entry,i) => deck.push({...entry, position:(i+0.5)/entries.length,key}));
  }
  return deck.sort((a,b) => a.position - b.position || a.key.localeCompare(b.key));
}
let welcomeDeckCache=null,welcomeDeckQuotes=null,welcomeDeckProfiles=null;
function welcomeSelection(time) {
  const profiles=teacherCache?.profiles||[];
  if(welcomeDeckQuotes!==wisdomCache||welcomeDeckProfiles!==profiles){
    welcomeDeckCache=welcomeDeck(wisdomCache,profiles);
    welcomeDeckQuotes=wisdomCache;welcomeDeckProfiles=profiles;
  }
  if(!welcomeDeckCache.length)return {};
  const epoch=Math.floor(Date.parse('2026-10-24T00:00:00Z')/86400000)*4;
  const index=((time.serial-epoch)%welcomeDeckCache.length+welcomeDeckCache.length)%welcomeDeckCache.length;
  return welcomeDeckCache[index];
}

// v1.19.1: tải kho câu có giới hạn thời gian (trước đây một yêu cầu treo làm lời chào kẹt mãi) và thử lại sau 5/10/15 giây khi lỗi mạng.
async function welcomeFetchJson(url,ms=8000){const c=new AbortController(),t=setTimeout(()=>c.abort(),ms);try{const r=await fetch(url,{signal:c.signal});if(!r.ok)throw Error(url);return await r.json();}finally{clearTimeout(t);}}
const welcomeRetries=new Map();
function welcomeRetryLater(key){const n=(welcomeRetries.get(key)||0)+1;welcomeRetries.set(key,n);if(n<=3)setTimeout(dailyWelcome,5000*n);}
// Mốc đổi buổi theo giờ Việt Nam (UTC+7, không có giờ mùa hè): 05:00, 11:00, 14:00, 18:00. Trả về số mili giây tới mốc kế tiếp.
function welcomeNextBoundary(now=Date.now()){const day=86400000,t=(((now+7*3600000)%day)+day)%day,marks=[5,11,14,18].map(h=>h*3600000),next=marks.find(m=>m>t);return (next===undefined?marks[0]+day:next)-t;}
function scheduleWelcomeBoundary(){setTimeout(()=>{dailyWelcome();scheduleWelcomeBoundary();},welcomeNextBoundary()+1500);}
async function dailyWelcome(force=false){
 if(!currentUser||document.hidden||welcomeLoading||$('#editor').open||document.querySelector('.welcome-dialog'))return;
 const owner=currentUser.id,time=welcomeSlot(),key='zen-welcome:'+owner+':'+time.day+':'+time.slot;
 if(!force&&(localRead(key)||welcomeSession.has(key)))return;
 welcomeLoading=true;
 try{
  // v1.19.1: dấu đã đọc của máy chủ chỉ để không hiện trùng giữa các thiết bị. Máy chủ chậm hoặc lỗi thì vẫn chào (dấu trên máy này chặn lặp lại), không để lời chào im lặng.
  await Promise.race([loadReadReceipts(),new Promise(r=>setTimeout(r,6000))]);
  if(!force&&readReceiptOwner===owner&&readReceiptKeys.has(welcomeReceipt(time)))return;
  if(!wisdomCache)wisdomCache=(await welcomeFetchJson('/wisdom.json')).filter(q=>typeof q.vi==='string'&&q.vi.trim());
  if(!teacherCache){try{teacherCache=await welcomeFetchJson('/teachers.json');}catch{}}
  if(currentUser?.id!==owner||$('#editor').open)return;
  const {quote:q,profile}=welcomeSelection(time);if(!q)return;
  const d=document.createElement('dialog');d.className='welcome-dialog';if(force)d.dataset.manual='true';d.setAttribute('aria-labelledby','welcome-title');
  d.innerHTML=`<button type="button" class="welcome-close" aria-label="Đóng lời chào" title="Đóng">×</button><div class="welcome-content"><header class="welcome-heading"><span class="welcome-lotus" aria-hidden="true">❀</span><p class="eyebrow">${esc(time.label)} · MỘT KHOẢNH KHẮC CHO BẠN</p><h2 id="welcome-title">Chào mừng bạn trở lại</h2><p class="welcome-intro">Dừng một nhịp, rồi bắt đầu điều có ý nghĩa.</p></header><blockquote lang="vi">${esc(q.vi)}</blockquote><div class="wisdom-teacher">${profile?.image?'<img src="'+esc(profile.image)+'" alt="'+esc(profile.imageAlt||profile.name)+'" width="48" height="48">':''}<span><strong>${esc(profile?.name||q.author)}</strong><small>${esc(profile?.theme||q.attribution||'Một điều để chiêm nghiệm')}</small></span></div><details class="welcome-sources"><summary>Nguồn & thông tin trích dẫn</summary><p class="wisdom-kind">${esc(q.translationNote||'Bản dịch tiếng Việt · tham khảo')}</p><p class="wisdom-author">${esc(q.attribution||q.author)}</p><a href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">${esc(q.source)} ↗</a>${q.contextUrl?'<a href="'+esc(q.contextUrl)+'" target="_blank" rel="noopener noreferrer">Giải nghĩa trích đoạn ↗</a>':''}${profile?.imageSource?'<a href="'+esc(profile.imageSource)+'" target="_blank" rel="noopener noreferrer">Nguồn ảnh chân dung ↗</a>':''}<details class="wisdom-directory"><summary>Thư viện · ${wisdomCache.filter(q=>q.kind!=='reflection').length} trích đoạn có nguồn</summary><p>Bản dịch nghĩa mang tính tham khảo. Lời biên soạn của Zen Studio được ghi riêng, không phải phát ngôn của vị thầy.</p>${(teacherCache?.profiles||[]).filter(welcomeAllowed).map(p=>'<a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">'+esc(p.name)+' · '+esc(p.theme)+'</a>').join('')}</details></details><footer class="welcome-actions"><button type="button" class="btn primary" id="welcome-read">${svgIcon('check')}Đã đọc · Bắt đầu làm việc</button><small>Không tự hiện lại trên các thiết bị của bạn. Có thể mở lại từ Thông báo.</small><p id="welcome-read-status" role="status" hidden></p></footer></div>`;
  document.body.append(d);d.addEventListener('close',()=>d.remove());d.querySelector('.welcome-close').onclick=()=>d.close();
  const portrait=d.querySelector('.wisdom-teacher img');portrait?.addEventListener('error',()=>portrait.remove(),{once:true});
  d.querySelector('#welcome-read').onclick=async e=>{const button=e.currentTarget,status=d.querySelector('#welcome-read-status');button.disabled=true;try{await saveReadReceipts([welcomeReceipt(time)]);d.close();}catch{status.hidden=false;status.textContent='Chưa lưu được xác nhận. Kiểm tra kết nối rồi thử lại.';button.disabled=false;}};
  d.showModal();d.scrollTop=0;welcomeSession.add(key);localWrite(key,'seen');
 }catch{welcomeRetryLater(key);}finally{welcomeLoading=false;}
}
const beforeWelcomeRender=render;render=function(){beforeWelcomeRender();if(currentUser)loadReadReceipts();setTimeout(dailyWelcome,700);};
setInterval(checkRelease,300000);setInterval(dailyWelcome,60000);window.addEventListener('focus',()=>{checkRelease();dailyWelcome();});setTimeout(dailyWelcome,1000);refreshBell();
// v1.19.1: chào ngay khi tab hiện lại, khi có mạng lại, khi quay lại từ bộ nhớ đệm trang, và đúng lúc sang buổi mới (không đợi nhịp 60 giây).
document.addEventListener('visibilitychange',()=>{if(!document.hidden){checkRelease();dailyWelcome();}});window.addEventListener('online',()=>dailyWelcome());window.addEventListener('pageshow',e=>{if(e.persisted)dailyWelcome();});scheduleWelcomeBoundary();
function noticeSignature(t){return [t.id,t.notice,t.due||'',t.title,t.important].join('|');}
function seenNotices(){let local=[];try{local=JSON.parse(localRead('zen-notices:'+currentUser?.id)||'[]');}catch{}return [...new Set([...local,...[...(readReceiptOwner===currentUser?.id?readReceiptKeys:[])].filter(k=>k.startsWith('notice:')).map(k=>{try{return decodeURIComponent(k.slice(7));}catch{return '';}})])];}
async function markNoticesRead(){await saveReadReceipts(['release:'+latestVersion,...taskNotices().map(noticeReceipt)]);localWrite('zen-notices:'+currentUser?.id,JSON.stringify(taskNotices().map(noticeSignature)));fileAlerts=[];localWrite(releaseKey(),latestVersion);refreshBell();}
refreshBell=function(){const seen=new Set(seenNotices()),count=taskNotices().filter(t=>!seen.has(noticeSignature(t))).length+fileAlerts.length+(releaseUnread()?1:0);bell.innerHTML=svgIcon('bell')+(count?'<span class="notification-count">'+(count>99?'99+':count)+'</span>':'');bell.setAttribute('aria-label','Thông báo · '+count+' chưa xem');};
const beforeReadBell=bell.onclick;bell.onclick=()=>{beforeReadBell();const b=$('#clear-file-alerts');b.textContent='Xác nhận đã đọc tất cả';const tools=document.createElement('div');tools.className='notice-read-toolbar';$('#editor-body .notice-list').before(tools);tools.append(b);b.onclick=async()=>{b.disabled=true;try{await markNoticesRead();$('#editor').close();}catch{b.disabled=false;notify('Chưa lưu được xác nhận. Kiểm tra kết nối rồi thử lại.');}};const open=document.createElement('button');open.type='button';open.className='btn welcome-reopen';open.textContent='❀ Một điều để chiêm nghiệm';open.onclick=()=>{$('#editor').close();dailyWelcome(true);};$('#editor-body').append(open);const seen=new Set(seenNotices());document.querySelectorAll('.notice-list [data-task]').forEach(el=>{const t=taskNotices().find(t=>t.id===el.dataset.task&&t.project.id===el.dataset.pid);if(t&&seen.has(noticeSignature(t)))el.closest('.notice-item')?.remove();});};
const beforeNextCard=taskCard;taskCard=function(t,p){const html=beforeNextCard(t,p),next=p.columns[p.columns.indexOf(t.col)+1];return next?html.replace('</article>',`<button type="button" class="btn task-next" data-next-task="${esc(t.id)}" data-next-project="${esc(p.id)}">${svgIcon('check')}Chuyển sang ${esc(next)} →</button></article>`):html;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-next-task]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const p=project(b.dataset.nextProject),t=p?.tasks.find(t=>t.id===b.dataset.nextTask);if(!t)return;const next=p.columns[p.columns.indexOf(t.col)+1];if(!next)return;t.col=next;if(next==='Done'){t.checks.forEach(c=>c.done=true);celebrateCompletion(completionKindFor(p,t));}save();render();},true);
refreshBell();

// Opening a task notice marks only that notice as seen, then opens its task editor.
document.addEventListener('click',e=>{const target=e.target.closest('.notice-list [data-task]');if(!target)return;const notice=taskNotices().find(t=>t.id===target.dataset.task&&t.project.id===target.dataset.pid);if(notice){const seen=new Set(seenNotices());seen.add(noticeSignature(notice));saveReadReceipts([noticeReceipt(notice)]).catch(()=>{});localWrite('zen-notices:'+currentUser?.id,JSON.stringify([...seen]));refreshBell();}},true);



setInterval(()=>{if(currentUser&&!document.hidden)loadReadReceipts();},10000);
window.addEventListener('focus',()=>loadReadReceipts(true));
